const GAME_HTML = "<div id=\"landing\">\n    <nav class=\"landing-nav\">\n      <div class=\"brand-mark\">庭院防线</div>\n      <div class=\"nav-actions\">\n        <button type=\"button\" class=\"chip\" id=\"navLbBtn\">通关榜</button>\n        <button type=\"button\" class=\"chip\" id=\"navEndlessBtn\">无尽</button>\n      </div>\n    </nav>\n    <section class=\"hero\">\n      <h1 class=\"hero-brand\">植物大战僵尸</h1>\n      <p class=\"hero-line\">从晨光草坪到月下墓园，守护你的庭院。选关即开打。</p>\n      <div class=\"hero-cta\">\n        <button type=\"button\" class=\"btn-primary\" id=\"ctaScroll\">选择关卡</button>\n        <button type=\"button\" class=\"btn-ghost\" id=\"ctaWeekly\">每周挑战</button>\n      </div>\n    </section>\n    <section class=\"panel\" id=\"playPanel\">\n      <div class=\"panel-head\">\n        <div>\n          <div class=\"panel-title\" id=\"panelTitle\">白天冒险</div>\n          <div class=\"panel-sub\" id=\"panelSub\">1-1 至 1-10 · 阳光与豌豆</div>\n        </div>\n        <div style=\"display:flex; flex-direction:column; gap:10px; align-items:flex-end;\">\n          <div class=\"seg\" id=\"worldSeg\">\n            <button type=\"button\" data-world=\"day\" class=\"active\">白天</button>\n            <button type=\"button\" data-world=\"night\">黑夜</button>\n          </div>\n          <div class=\"seg\" id=\"diffSeg\">\n            <button type=\"button\" data-diff=\"easy\">简单</button>\n            <button type=\"button\" data-diff=\"normal\" class=\"active\">普通</button>\n            <button type=\"button\" data-diff=\"hard\">困难</button>\n          </div>\n        </div>\n      </div>\n      <div class=\"level-grid\" id=\"levelGrid\"></div>\n      <div class=\"mode-row\">\n        <button type=\"button\" class=\"btn-ghost\" id=\"btnEndless\">无尽模式</button>\n        <button type=\"button\" class=\"btn-ghost\" id=\"btnLb\">排行榜</button>\n      </div>\n    </section>\n  </div>\n\n  <div id=\"lbModal\" class=\"hidden\" aria-hidden=\"true\">\n    <div class=\"lb-card\">\n      <h2 id=\"lbTitle\">通关次数排行榜</h2>\n      <div class=\"lb-tabs\">\n        <button type=\"button\" data-tab=\"clears\" class=\"active\">通关次数</button>\n        <button type=\"button\" data-tab=\"sun\">本周阳光</button>\n      </div>\n      <div class=\"lb-list\" id=\"lbList\"></div>\n      <p class=\"lb-note\" id=\"lbNote\"></p>\n      <div class=\"lb-actions\">\n        <button type=\"button\" class=\"btn-primary\" id=\"lbCloseBtn\">返回</button>\n      </div>\n    </div>\n  </div>\n\n  <div id=\"app\" class=\"hidden\">\n    <div id=\"wrap\">\n      <canvas id=\"game\" width=\"900\" height=\"560\"></canvas>\n      <input id=\"cheatInput\" type=\"password\" autocomplete=\"off\">\n      <div id=\"overlay\">\n        <h2 id=\"ovTitle\"></h2>\n        <p id=\"ovText\"></p>\n        <div id=\"ovLeaderboard\"></div>\n        <div class=\"ov-actions\">\n          <button id=\"ovNextBtn\" style=\"display:none\">下一关</button>\n          <button id=\"ovBtn\" class=\"secondary\">再来一局</button>\n          <button id=\"ovMenuBtn\" class=\"ghost\">返回主菜单</button>\n        </div>\n      </div>\n    </div>\n    <p class=\"tip\">植物过多先选卡 · 点阳光收集 · 铲子移除 · ESC / P 暂停</p>\n  </div>";
const GAME_CSS = "@import url(\"https://fonts.googleapis.com/css2?family=Fredoka:wght@500;600;700&family=Noto+Sans+SC:wght@400;500;700&family=ZCOOL+QingKe+HuangYou&display=swap\");\n\n:root {\n  --ink: #142016;\n  --moss: #2f6b3a;\n  --leaf: #5dae4a;\n  --sun: #f2b84a;\n  --amber: #e8892c;\n  --cream: #f7f1e3;\n  --night: #0b1520;\n  --moon: #d9e7f2;\n  --mist: rgba(255,255,255,.08);\n  --ease: cubic-bezier(.22,1,.36,1);\n}\n* { margin:0; padding:0; box-sizing:border-box; }\nhtml, body { min-height:100%; }\nbody {\n  font-family: \"Noto Sans SC\", \"PingFang SC\", sans-serif;\n  color: var(--cream);\n  background: #08110c;\n  overflow-x: hidden;\n}\nbutton { font: inherit; cursor: pointer; border: none; background: none; color: inherit; }\n.hidden { display: none !important; }\n\n/* ===== Landing ===== */\n#landing {\n  position: relative; min-height: 100vh;\n  display: flex; flex-direction: column;\n  isolation: isolate;\n}\n#landing::before {\n  content:\"\"; position:fixed; inset:0; z-index:-2;\n  background:\n    linear-gradient(105deg, rgba(18,42,22,.55) 0%, rgba(8,16,24,.35) 48%, rgba(8,14,28,.72) 100%),\n    var(--hero-bg, none) center/cover no-repeat;\n  transform: scale(1.04);\n  animation: heroDrift 18s ease-in-out infinite alternate;\n}\n#landing::after {\n  content:\"\"; position:fixed; inset:0; z-index:-1;\n  background:\n    radial-gradient(ellipse 50% 40% at 15% 20%, rgba(255,200,90,.18), transparent 55%),\n    radial-gradient(ellipse 45% 50% at 85% 70%, rgba(80,140,180,.16), transparent 50%),\n    linear-gradient(to top, rgba(5,10,8,.78), transparent 42%);\n  pointer-events: none;\n}\n@keyframes heroDrift { from { transform: scale(1.04) translateY(0); } to { transform: scale(1.08) translateY(-1.5%); } }\n\n.landing-nav {\n  display:flex; justify-content:space-between; align-items:center;\n  padding: 22px clamp(20px,4vw,56px); position: relative; z-index: 2;\n}\n.brand-mark {\n  font-family: \"ZCOOL QingKe HuangYou\", \"Fredoka\", sans-serif;\n  font-size: 1.15rem; letter-spacing: .08em; color: #fff;\n  text-shadow: 0 2px 16px rgba(0,0,0,.35);\n}\n.nav-actions { display:flex; gap:10px; }\n.chip {\n  padding: 10px 16px; border-radius: 999px;\n  border: 1px solid rgba(255,255,255,.22);\n  background: rgba(255,255,255,.08);\n  backdrop-filter: blur(10px);\n  transition: transform .25s var(--ease), background .25s, border-color .25s;\n}\n.chip:hover { transform: translateY(-2px); background: rgba(255,255,255,.14); }\n.chip.active {\n  background: rgba(232,137,44,.9); border-color: transparent; color:#fff;\n  box-shadow: 0 8px 24px rgba(232,137,44,.35);\n}\n\n.hero {\n  flex: 1; display:flex; flex-direction:column; justify-content:flex-end;\n  padding: 0 clamp(20px,5vw,72px) clamp(28px,5vh,56px);\n  max-width: 1200px; width: 100%; margin: 0 auto;\n  min-height: min(78vh, 720px);\n}\n.hero-brand {\n  font-family: \"ZCOOL QingKe HuangYou\", \"Fredoka\", sans-serif;\n  font-size: clamp(3.2rem, 9vw, 6.4rem);\n  line-height: .95; letter-spacing: .04em;\n  color: #fff;\n  text-shadow: 0 4px 0 rgba(0,0,0,.18), 0 18px 50px rgba(0,0,0,.35);\n  max-width: 12ch;\n  animation: rise .9s var(--ease) both;\n}\n.hero-line {\n  margin-top: 18px; max-width: 34ch;\n  font-size: clamp(1rem, 2vw, 1.2rem); font-weight: 500;\n  color: rgba(247,241,227,.88); line-height: 1.55;\n  animation: rise .9s var(--ease) .12s both;\n}\n.hero-cta { margin-top: 28px; display:flex; flex-wrap:wrap; gap:12px; animation: rise .9s var(--ease) .22s both; }\n.btn-primary, .btn-ghost {\n  display:inline-flex; align-items:center; justify-content:center; gap:8px;\n  min-height: 52px; padding: 0 26px; border-radius: 999px;\n  font-weight: 700; letter-spacing: .02em;\n  transition: transform .25s var(--ease), box-shadow .25s, background .25s;\n}\n.btn-primary {\n  background: linear-gradient(135deg, #f0a33a, #e06a1a);\n  color: #fff; box-shadow: 0 12px 32px rgba(224,106,26,.4);\n}\n.btn-primary:hover { transform: translateY(-3px) scale(1.02); }\n.btn-ghost {\n  border: 1px solid rgba(255,255,255,.28);\n  background: rgba(255,255,255,.08); backdrop-filter: blur(8px);\n}\n.btn-ghost:hover { transform: translateY(-2px); background: rgba(255,255,255,.14); }\n@keyframes rise {\n  from { opacity:0; transform: translateY(28px); }\n  to { opacity:1; transform: translateY(0); }\n}\n\n.panel {\n  width: min(1100px, calc(100% - 32px));\n  margin: 0 auto 40px;\n  padding: 22px;\n  border-radius: 28px;\n  background: rgba(10,18,14,.55);\n  border: 1px solid rgba(255,255,255,.12);\n  backdrop-filter: blur(18px) saturate(1.2);\n  box-shadow: 0 30px 80px rgba(0,0,0,.35);\n  animation: rise 1s var(--ease) .3s both;\n}\n.panel.night-theme {\n  background: rgba(8,14,24,.62);\n  border-color: rgba(180,210,230,.14);\n}\n.panel-head {\n  display:flex; flex-wrap:wrap; gap:14px; justify-content:space-between; align-items:end;\n  margin-bottom: 18px;\n}\n.panel-title {\n  font-family: \"Fredoka\", \"Noto Sans SC\", sans-serif;\n  font-size: 1.35rem; font-weight: 700;\n}\n.panel-sub { color: rgba(247,241,227,.65); font-size: .92rem; margin-top: 4px; }\n.seg {\n  display:inline-flex; padding:4px; border-radius:999px;\n  background: rgba(255,255,255,.06); border: 1px solid rgba(255,255,255,.1);\n  gap: 4px;\n}\n.seg button {\n  min-width: 88px; padding: 10px 14px; border-radius: 999px;\n  font-weight: 600; font-size: .9rem; color: rgba(255,255,255,.7);\n  transition: .2s var(--ease);\n}\n.seg button:hover { color:#fff; }\n.seg button.active {\n  background: #fff; color: #16301c;\n  box-shadow: 0 6px 18px rgba(0,0,0,.2);\n}\n.panel.night-theme .seg button.active { background: var(--moon); color: #102030; }\n\n.level-grid {\n  display:grid;\n  grid-template-columns: repeat(5, minmax(0,1fr));\n  gap: 10px;\n}\n@media (max-width: 820px) {\n  .level-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }\n}\n.level-btn {\n  position: relative; text-align:left;\n  padding: 16px 14px 14px;\n  border-radius: 18px;\n  border: 1px solid rgba(255,255,255,.1);\n  background:\n    linear-gradient(160deg, rgba(255,255,255,.1), rgba(255,255,255,.02));\n  transition: transform .22s var(--ease), border-color .22s, background .22s;\n  overflow: hidden;\n}\n.level-btn::before {\n  content:\"\"; position:absolute; inset:auto -20% -40% auto; width:90px; height:90px;\n  border-radius:50%; background: rgba(93,174,74,.25); filter: blur(8px);\n  transition: transform .35s var(--ease);\n}\n.panel.night-theme .level-btn::before { background: rgba(120,170,210,.22); }\n.level-btn:hover {\n  transform: translateY(-4px);\n  border-color: rgba(255,255,255,.28);\n  background: linear-gradient(160deg, rgba(255,255,255,.16), rgba(255,255,255,.04));\n}\n.level-btn:hover::before { transform: scale(1.35); }\n.level-btn .lv-id {\n  font-family: \"Fredoka\", sans-serif; font-weight: 700; font-size: 1.15rem;\n  position: relative;\n}\n.level-btn .lv-sub {\n  position: relative; margin-top: 6px;\n  font-size: .78rem; color: rgba(247,241,227,.62);\n}\n.level-btn.final {\n  border-color: rgba(232,137,44,.45);\n  background: linear-gradient(160deg, rgba(232,137,44,.28), rgba(255,255,255,.04));\n}\n.mode-row {\n  display:flex; flex-wrap:wrap; gap:10px; margin-top: 16px;\n}\n.mode-row .btn-ghost, .mode-row .btn-primary { min-height: 46px; font-size: .95rem; }\n\n/* ===== Leaderboard modal ===== */\n#lbModal {\n  position: fixed; inset: 0; z-index: 40;\n  display: flex; align-items: center; justify-content: center;\n  padding: 24px 16px;\n  background:\n    radial-gradient(ellipse 50% 40% at 20% 20%, rgba(255,190,80,.12), transparent 55%),\n    radial-gradient(ellipse 45% 50% at 80% 70%, rgba(80,140,180,.14), transparent 50%),\n    rgba(6,12,10,.72);\n  backdrop-filter: blur(14px) saturate(1.15);\n  animation: rise .45s var(--ease) both;\n}\n#lbModal.hidden { display: none !important; }\n.lb-card {\n  width: min(520px, 100%);\n  max-height: min(82vh, 640px);\n  overflow: auto;\n  border-radius: 28px;\n  padding: 26px 24px 22px;\n  background: rgba(12,20,16,.72);\n  border: 1px solid rgba(255,255,255,.14);\n  box-shadow: 0 30px 80px rgba(0,0,0,.45);\n  color: var(--cream);\n}\n.lb-card h2 {\n  font-family: \"ZCOOL QingKe HuangYou\", \"Fredoka\", sans-serif;\n  font-size: 1.7rem; text-align: center; margin-bottom: 14px;\n  letter-spacing: .04em;\n}\n.lb-tabs {\n  display: flex; gap: 8px; justify-content: center; margin-bottom: 16px;\n}\n.lb-tabs button {\n  min-width: 132px; padding: 10px 14px; border-radius: 999px;\n  border: 1px solid rgba(255,255,255,.14);\n  background: rgba(255,255,255,.06);\n  font-weight: 600; color: rgba(247,241,227,.72);\n  transition: .2s var(--ease);\n}\n.lb-tabs button:hover { color: #fff; background: rgba(255,255,255,.12); }\n.lb-tabs button.active {\n  background: linear-gradient(135deg, #f0a33a, #e06a1a);\n  border-color: transparent; color: #fff;\n  box-shadow: 0 8px 22px rgba(224,106,26,.35);\n}\n.lb-list { display: flex; flex-direction: column; gap: 8px; min-height: 180px; }\n.lb-item {\n  display: flex; align-items: center; justify-content: space-between; gap: 12px;\n  padding: 12px 14px; border-radius: 14px;\n  background: rgba(255,255,255,.05);\n  border: 1px solid rgba(255,255,255,.06);\n}\n.lb-item.top {\n  background: linear-gradient(135deg, rgba(242,184,74,.18), rgba(255,255,255,.04));\n  border-color: rgba(242,184,74,.28);\n}\n.lb-item .rank { width: 2.2em; font-weight: 700; color: #f2b84a; }\n.lb-item .name { flex: 1; text-align: left; color: rgba(247,241,227,.92); }\n.lb-item .val { font-weight: 700; color: #f2b84a; }\n.lb-empty {\n  text-align: center; color: rgba(247,241,227,.55);\n  padding: 48px 12px; line-height: 1.6;\n}\n.lb-note {\n  margin: 14px 0 16px; text-align: center;\n  font-size: .78rem; color: rgba(247,241,227,.45); line-height: 1.45;\n}\n.lb-actions { display: flex; justify-content: center; }\n\n/* ===== Game shell ===== */\n#app {\n  min-height: 100vh; display:flex; flex-direction:column; align-items:center;\n  justify-content:center; padding: 16px 12px 24px;\n  background:\n    radial-gradient(ellipse 70% 50% at 50% 0%, rgba(80,120,60,.25), transparent 55%),\n    #0d1610;\n}\n#app.night-mode {\n  background:\n    radial-gradient(ellipse 60% 45% at 70% 10%, rgba(90,130,170,.2), transparent 50%),\n    #070c14;\n}\n#wrap {\n  position: relative; width: min(960px, 100%);\n  border-radius: 20px; overflow: hidden;\n  box-shadow: 0 24px 64px rgba(0,0,0,.45), 0 0 0 1px rgba(255,255,255,.08);\n  background: #1a2a18;\n}\n#app.night-mode #wrap { background: #101820; }\ncanvas { display:block; width:100%; height:auto; cursor:pointer; }\n#overlay {\n  position:absolute; inset:0; display:none;\n  align-items:center; justify-content:center;\n  background: rgba(8,12,10,.68); backdrop-filter: blur(8px);\n  flex-direction:column; color:#fff; text-align:center; padding:20px;\n}\n#overlay.show { display:flex; }\n#overlay h2 {\n  font-family: \"ZCOOL QingKe HuangYou\", \"Fredoka\", sans-serif;\n  font-size: clamp(2rem, 5vw, 2.8rem); margin-bottom:10px;\n  text-shadow: 0 4px 24px rgba(0,0,0,.4);\n}\n#overlay p { font-size:16px; opacity:.92; margin-bottom:14px; max-width:420px; line-height:1.55; }\n#ovLeaderboard {\n  max-width:420px; width:100%; margin-bottom:18px; text-align:left;\n  background: rgba(0,0,0,.3); border-radius:14px; padding:12px 18px;\n  border:1px solid rgba(255,255,255,.12);\n}\n#ovLeaderboard h3 { font-size:16px; color:#f2c14b; margin-bottom:8px; text-align:center; }\n#ovLeaderboard .lb-row { font-size:14px; line-height:1.8; display:flex; justify-content:space-between; }\n#ovLeaderboard .lb-note { font-size:12px; color:rgba(255,255,255,.45); text-align:center; margin-top:8px; }\n#overlay .ov-actions { display:flex; gap:12px; flex-wrap:wrap; justify-content:center; }\n#overlay button {\n  padding:12px 26px; font-size:16px; border:none; border-radius:999px;\n  background: linear-gradient(135deg,#f0a33a,#e06a1a); color:#fff;\n  cursor:pointer; font-weight:700; box-shadow:0 8px 22px rgba(224,106,26,.35);\n  transition: transform .2s var(--ease);\n}\n#overlay button.secondary { background: linear-gradient(135deg,#6ecf5a,#3d9a36); box-shadow:0 8px 22px rgba(61,154,54,.3); }\n#overlay button.ghost { background: rgba(255,255,255,.12); box-shadow:none; border:1px solid rgba(255,255,255,.22); }\n#overlay button:hover { transform: translateY(-2px) scale(1.03); }\n.tip {\n  margin-top: 12px; font-size:12px; color: rgba(247,241,227,.55);\n  padding: 8px 14px; border-radius:999px; background: rgba(255,255,255,.06);\n}\n#cheatInput {\n  position:absolute; top:1.8%; left:85.3%; width:12.7%; height:6.4%;\n  font-size:14px; text-align:center; box-sizing:border-box;\n  border:2px solid #8b5a2b; border-radius:6px;\n  background:rgba(255,255,255,.95); color:#5a4a3a;\n  z-index:10; display:none; outline:none;\n}\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { animation: none !important; transition: none !important; }\n}\n";

// 客户端游戏脚本：自包含，所有常量在脚本内部定义。
// window.__SEED__ 由 webview handler 注入；本地预览时为 undefined，回退到 Date.now()。
const GAME_JS = "window.__ASSETS__={\"hero\":\"data:image/webp;base64,\",\"nightLawn\":\"data:image/webp;base64,\",\"dayLawn\":\"data:image/webp;base64,\",\"house\":\"data:image/webp;base64,\",\"mower\":\"data:image/webp;base64,\"};\n\n\"use strict\";\n/* ===== 基础工具 ===== */\nconst C = document.getElementById(\"game\");\nconst ctx = C.getContext(\"2d\");\nconst W = C.width, H = C.height;\nconst landingEl = document.getElementById(\"landing\");\nconst appEl = document.getElementById(\"app\");\nconst playPanel = document.getElementById(\"playPanel\");\nconst levelGrid = document.getElementById(\"levelGrid\");\nconst ASSETS = Object.assign({\n  hero: \"assets/hero-bg.jpg\",\n  nightLawn: \"assets/night-lawn.jpg\",\n  dayLawn: \"assets/day-lawn.jpg\",\n  house: \"assets/house-side.png\",\n  mower: \"assets/mower-cart.png\"\n}, window.__ASSETS__ || {});\nif(ASSETS.hero) document.documentElement.style.setProperty(\"--hero-bg\", 'url(\"' + ASSETS.hero + '\")');\n\nlet nightLawnImg = null, nightLawnReady = false;\nlet dayLawnImg = null, dayLawnReady = false;\nlet houseImg = null, houseReady = false;\nlet mowerImg = null, mowerReady = false;\nfunction loadImg(src){\n  return new Promise((resolve, reject)=>{\n    const img = new Image();\n    img.onload = ()=> resolve(img);\n    img.onerror = ()=> reject(new Error(\"load fail: \" + src));\n    img.src = src;\n  });\n}\n(function loadArtAssets(){\n  loadImg(ASSETS.nightLawn).then(img=>{\n    nightLawnImg = img; nightLawnReady = true;\n  }).catch(()=>{ nightLawnReady = false; });\n  loadImg(ASSETS.dayLawn).then(img=>{\n    dayLawnImg = img; dayLawnReady = true;\n  }).catch(()=>{ dayLawnReady = false; });\n  loadImg(ASSETS.house).then(img=>{\n    houseImg = img; houseReady = true;\n  }).catch(()=>{ houseReady = false; });\n  loadImg(ASSETS.mower).then(img=>{\n    mowerImg = img; mowerReady = true;\n  }).catch(()=>{ mowerReady = false; });\n})();\nfunction drawPlantIcon(key, now, i){\n  const fake = {anim:now, hp:(PLANTS[key]&&PLANTS[key].hp)||300, cx:i||0, armed:true, grown:true};\n  if(key===\"sunflower\") drawSunflower(fake);\n  else if(key===\"peashooter\") drawPeashooter(fake);\n  else if(key===\"repeaterpea\") drawRepeater(fake);\n  else if(key===\"snowpea\") drawSnowPea(fake);\n  else if(key===\"chomper\") drawChomper(fake);\n  else if(key===\"threepeater\") drawThreepeater(fake);\n  else if(key===\"wallnut\") drawWallnut(fake);\n  else if(key===\"potatomine\") drawPotato(fake);\n  else if(key===\"cherrybomb\") drawCherry(fake);\n  else if(key===\"puffshroom\") drawPuffShroom(fake);\n  else if(key===\"sunshroom\") drawSunShroom(fake);\n  else if(key===\"fumeshroom\") drawFumeShroom(fake);\n  else if(key===\"gravebuster\") drawGraveBuster(fake);\n  else if(key===\"hypnoshroom\") drawHypnoShroom(fake);\n  else if(key===\"scaredyshroom\") drawScaredyShroom(fake);\n  else if(key===\"iceshroom\") drawIceShroom(fake);\n  else if(key===\"doomshroom\") drawDoomShroom(fake);\n}\nfunction showLanding(){\n  if(landingEl) landingEl.classList.remove(\"hidden\");\n  if(appEl) appEl.classList.add(\"hidden\");\n  state = \"menu\";\n  paused = false;\n  if(overlay) overlay.classList.remove(\"show\");\n  closeLeaderboardModal();\n  refreshLandingLevels();\n}\nfunction showGameShell(){\n  if(landingEl) landingEl.classList.add(\"hidden\");\n  if(appEl){\n    appEl.classList.remove(\"hidden\");\n    if(isNightLevel()) appEl.classList.add(\"night-mode\");\n    else appEl.classList.remove(\"night-mode\");\n  }\n}\nfunction refreshLandingLevels(){\n  if(!levelGrid) return;\n  const list = getWorldLevels();\n  const night = curWorld === \"night\";\n  if(playPanel) playPanel.classList.toggle(\"night-theme\", night);\n  const title = document.getElementById(\"panelTitle\");\n  const sub = document.getElementById(\"panelSub\");\n  if(title) title.textContent = night ? \"黑夜冒险\" : \"白天冒险\";\n  if(sub) sub.textContent = night ? \"2-1 至 2-10 · 蘑菇与墓园\" : \"1-1 至 1-10 · 阳光与豌豆\";\n  levelGrid.innerHTML = \"\";\n  list.forEach((lv)=>{\n    const btn = document.createElement(\"button\");\n    btn.type = \"button\";\n    btn.className = \"level-btn\" + (lv.id === list.length-1 ? \" final\" : \"\");\n    const short = (lv.title || \"\").replace(/^(白天|黑夜)\\s*/, \"\");\n    btn.innerHTML = '<div class=\"lv-id\">'+short+'</div><div class=\"lv-sub\">'+(lv.sub||\"\")+'</div>';\n    btn.addEventListener(\"click\", ()=> newGame(window.__SEED__, lv.id, \"normal\", curWorld));\n    levelGrid.appendChild(btn);\n  });\n  document.querySelectorAll(\"#worldSeg button\").forEach(b=>{\n    b.classList.toggle(\"active\", b.getAttribute(\"data-world\") === curWorld);\n  });\n  document.querySelectorAll(\"#diffSeg button\").forEach(b=>{\n    b.classList.toggle(\"active\", b.getAttribute(\"data-diff\") === curDiff);\n  });\n}\nfunction bindLandingUI(){\n  document.querySelectorAll(\"#worldSeg button\").forEach(b=>{\n    b.addEventListener(\"click\", ()=>{\n      curWorld = b.getAttribute(\"data-world\") || \"day\";\n      ROWS = 5; GRID_Y = calcGridY(ROWS);\n      refreshLandingLevels();\n    });\n  });\n  document.querySelectorAll(\"#diffSeg button\").forEach(b=>{\n    b.addEventListener(\"click\", ()=>{\n      curDiff = b.getAttribute(\"data-diff\") || \"normal\";\n      refreshLandingLevels();\n    });\n  });\n  const scrollBtn = document.getElementById(\"ctaScroll\");\n  if(scrollBtn) scrollBtn.addEventListener(\"click\", ()=>{\n    const el = document.getElementById(\"playPanel\");\n    if(el) el.scrollIntoView({ behavior: \"smooth\", block: \"start\" });\n  });\n  const startWeekly = ()=> newGame(window.__SEED__, CLEAR_DAY_ID, \"weekly\", \"day\");\n  const startEndless = ()=> newGame(window.__SEED__, 0, \"endless\");\n  const w = document.getElementById(\"ctaWeekly\");\n  const e1 = document.getElementById(\"btnEndless\");\n  const e2 = document.getElementById(\"navEndlessBtn\");\n  const l1 = document.getElementById(\"btnLb\");\n  const l2 = document.getElementById(\"navLbBtn\");\n  if(w) w.addEventListener(\"click\", startWeekly);\n  if(e1) e1.addEventListener(\"click\", startEndless);\n  if(e2) e2.addEventListener(\"click\", startEndless);\n  if(l1) l1.addEventListener(\"click\", ()=> openLeaderboardModal());\n  if(l2) l2.addEventListener(\"click\", ()=> openLeaderboardModal());\n  document.querySelectorAll(\"#lbModal .lb-tabs button\").forEach(b=>{\n    b.addEventListener(\"click\", ()=>{\n      lbTab = b.getAttribute(\"data-tab\") || \"clears\";\n      renderLeaderboardModal();\n    });\n  });\n  const lbClose = document.getElementById(\"lbCloseBtn\");\n  if(lbClose) lbClose.addEventListener(\"click\", closeLeaderboardModal);\n  const lbModal = document.getElementById(\"lbModal\");\n  if(lbModal) lbModal.addEventListener(\"click\", e=>{\n    if(e.target === lbModal) closeLeaderboardModal();\n  });\n}\nfunction openLeaderboardModal(){\n  lbTab = lbTab || \"clears\";\n  const modal = document.getElementById(\"lbModal\");\n  if(modal){\n    modal.classList.remove(\"hidden\");\n    modal.setAttribute(\"aria-hidden\", \"false\");\n  }\n  if(landingEl) landingEl.classList.remove(\"hidden\");\n  if(appEl) appEl.classList.add(\"hidden\");\n  state = \"menu\";\n  renderLeaderboardModal();\n}\nfunction closeLeaderboardModal(){\n  const modal = document.getElementById(\"lbModal\");\n  if(modal){\n    modal.classList.add(\"hidden\");\n    modal.setAttribute(\"aria-hidden\", \"true\");\n  }\n}\nfunction renderLeaderboardModal(){\n  const listEl = document.getElementById(\"lbList\");\n  const titleEl = document.getElementById(\"lbTitle\");\n  const noteEl = document.getElementById(\"lbNote\");\n  if(!listEl) return;\n  document.querySelectorAll(\"#lbModal .lb-tabs button\").forEach(b=>{\n    b.classList.toggle(\"active\", b.getAttribute(\"data-tab\") === lbTab);\n  });\n  const weekId = (window.__WEEK__ && window.__WEEK__.id) || \"\";\n  if(titleEl){\n    titleEl.textContent = lbTab === \"clears\"\n      ? \"通关次数排行榜\"\n      : (\"本周排行榜 · \" + weekId);\n  }\n  if(noteEl){\n    noteEl.textContent = lbTab === \"clears\"\n      ? \"通关白天 1-10 或黑夜 2-10（普通/困难）记入排行榜\"\n      : (\"本周 \" + weekId + \" · 每周挑战通关收集的阳光可累积 · 每周一刷新\");\n  }\n  const rows = lbTab === \"clears\" ? (window.__LEADERBOARD__ || []) : (window.__WEEK_LEADERBOARD__ || []);\n  const valKey = lbTab === \"clears\" ? \"count\" : \"sun\";\n  const suffix = lbTab === \"clears\" ? \" 次\" : \" ☀\";\n  if(!rows.length){\n    listEl.innerHTML = '<div class=\"lb-empty\">' +\n      (lbTab === \"clears\"\n        ? \"暂无通关记录<br>快来成为第一个通关的人！\"\n        : \"本周暂无排行记录<br>参与每周挑战通关即可上榜！\") +\n      \"</div>\";\n    return;\n  }\n  listEl.innerHTML = rows.map((e,i)=>{\n    const medal = i===0?\"🥇\":i===1?\"🥈\":i===2?\"🥉\":(i+1)+\".\";\n    const name = (e.name||\"匿名\");\n    const shown = name.length>14 ? name.slice(0,14)+\"…\" : name;\n    return '<div class=\"lb-item'+(i<3?\" top\":\"\")+'\">' +\n      '<span class=\"rank\">'+medal+'</span>' +\n      '<span class=\"name\">'+shown+'</span>' +\n      '<span class=\"val\">'+(e[valKey]||0)+suffix+'</span></div>';\n  }).join(\"\");\n}\n\n/* 伪随机数生成器（可种子化，用于回放校验） */\nfunction makeRng(seed){\n  let s = seed >>> 0 || 1;\n  return function(){\n    s = (s * 1664525 + 1013904223) >>> 0;\n    return s / 4294967296;\n  };\n}\nlet rng = makeRng(Date.now() & 0xffffffff);\n\n/* ISO 周数（周一到周日），双端一致；服务端注入 window.__WEEK__ 时也用此算法 */\nfunction isoWeek(d){\n  const date = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));\n  const dayNum = date.getUTCDay() || 7;\n  date.setUTCDate(date.getUTCDate() + 4 - dayNum);\n  const yearStart = new Date(Date.UTC(date.getUTCFullYear(),0,1));\n  const weekNum = Math.ceil((((date - yearStart)/86400000) + 1)/7);\n  return date.getUTCFullYear() + \"W\" + String(weekNum).padStart(2,\"0\");\n}\n/* 每周僵尸组合：由 yearWeek 字符串哈希成种子确定性生成，全球本周相同 */\nfunction weeklyZombieSet(yearWeek){\n  return [\"normal\",\"flag\",\"newspaper\",\"football\",\"screendoor\",\"conehead\",\"buckethead\",\"polevaulter\"];\n}\n\n/* ===== 地图常量（参考 pypvz constants.py） ===== */\nconst COLS = 9;\nconst CELL_W = 78, CELL_H = 88;\nconst GRID_X = 132;\nlet ROWS = 5;\nlet GRID_Y = 122;\nfunction calcGridY(rows){ return 102 + Math.max(0, (H - 122 - rows*CELL_H)) / 2; }\nconst HOUSE_X = GRID_X - 30;\nconst SPAWN_X = GRID_X + COLS * CELL_W + 20;\n\n/* ===== 游戏数值（源自 pypvz constants.py，适配 web 节奏） ===== */\nlet INIT_SUN = 50;\nconst SUN_VALUE = 25;\nconst SUN_BOX_X = W - 110;\nconst SUN_BOX_Y = 28;\nconst SUN_DROP_INTERVAL = 10000;\nconst SUN_LIVE_TIME = 11000;\nconst PEA_INTERVAL = 1400;\nconst PEA_FIRST_DELAY = 700;\nconst BULLET_SPEED = 230;\nconst BULLET_DAMAGE = 20;\nconst SUNFLOWER_INTERVAL = 8000;\nconst SUNFLOWER_FIRST = 5000;\nconst ZOMBIE_SPEED = 14;\nconst ZOMBIE_HEALTH = 270;\nconst ZOMBIE_DAMAGE = 50;\nconst ZOMBIE_ATTACK_INTERVAL = 500;\nconst PLANT_HEALTH = 300;\nconst WALLNUT_HEALTH = 4000;\nconst POTATO_ARM_TIME = 14000;\nconst POTATO_DAMAGE = 1800;\nconst CHERRY_FUSE = 1200;\nconst CHERRY_DAMAGE = 1800;\nlet NUM_FLAGS = 2;\nconst CONEHEAD_HEALTH = 370;\nconst BUCKETHEAD_HEALTH = 1100;\nconst POLE_VAULTER_HEALTH = 500;\nconst NEWSPAPER_HEALTH = 200;\nconst NEWSPAPER_PAPER_HEALTH = 250;\nconst FOOTBALL_HEALTH = 270;\nconst FOOTBALL_HELMET_HEALTH = 1400;\nconst SCREENDOOR_HEALTH = 270;\nconst SCREENDOOR_SHIELD_HEALTH = 1100;\n\n/* ===== 关卡定义（对齐原版白天冒险 1-1～1-10） =====\n * 行数：1-1 单行 → 1-2/1-3 三行 → 1-4 起五路\n * 植物为「进入该关时已解锁」；通关后解锁下一植物（见 wiki / 攻略）\n * 1-5 原版为坚果保龄球，此处改为常规白天特训；1-10 原版为传送带，此处给全日植物池\n */\nconst DAY_PLANTS_FULL = [\"sunflower\",\"peashooter\",\"cherrybomb\",\"wallnut\",\"potatomine\",\"snowpea\",\"chomper\",\"repeaterpea\"];\nconst NIGHT_PLANTS_FULL = [\"sunshroom\",\"puffshroom\",\"fumeshroom\",\"scaredyshroom\",\"hypnoshroom\",\"gravebuster\",\"iceshroom\",\"doomshroom\",\"wallnut\",\"cherrybomb\",\"snowpea\",\"repeaterpea\"];\nconst DAY_LEVELS = [\n  { id:0, title:\"白天 1-1\", sub:\"单行草地\", rows:1, initSun:150, flags:1, night:false, graves:0, zombies:[\"normal\"],\n    plants:[\"peashooter\"] },\n  { id:1, title:\"白天 1-2\", sub:\"三行草地\", rows:3, initSun:50, flags:1, night:false, graves:0, zombies:[\"normal\"],\n    plants:[\"sunflower\",\"peashooter\"] },\n  { id:2, title:\"白天 1-3\", sub:\"路障僵尸\", rows:3, initSun:50, flags:1, night:false, graves:0, zombies:[\"normal\",\"conehead\"],\n    plants:[\"sunflower\",\"peashooter\",\"cherrybomb\"] },\n  { id:3, title:\"白天 1-4\", sub:\"五路全开\", rows:5, initSun:50, flags:1, night:false, graves:0, zombies:[\"normal\",\"conehead\"],\n    plants:[\"sunflower\",\"peashooter\",\"cherrybomb\",\"wallnut\"] },\n  { id:4, title:\"白天 1-5\", sub:\"白天特训\", rows:5, initSun:50, flags:1, night:false, graves:0, zombies:[\"normal\",\"conehead\"],\n    plants:[\"sunflower\",\"peashooter\",\"cherrybomb\",\"wallnut\"] },\n  { id:5, title:\"白天 1-6\", sub:\"撑杆来袭\", rows:5, initSun:50, flags:1, night:false, graves:0, zombies:[\"normal\",\"conehead\",\"polevaulter\"],\n    plants:[\"sunflower\",\"peashooter\",\"cherrybomb\",\"wallnut\",\"potatomine\"] },\n  { id:6, title:\"白天 1-7\", sub:\"寒冰登场\", rows:5, initSun:50, flags:2, night:false, graves:0, zombies:[\"normal\",\"conehead\",\"polevaulter\"],\n    plants:[\"sunflower\",\"peashooter\",\"cherrybomb\",\"wallnut\",\"potatomine\",\"snowpea\"] },\n  { id:7, title:\"白天 1-8\", sub:\"铁桶僵尸\", rows:5, initSun:50, flags:1, night:false, graves:0, zombies:[\"normal\",\"conehead\",\"polevaulter\",\"buckethead\"],\n    plants:[\"sunflower\",\"peashooter\",\"cherrybomb\",\"wallnut\",\"potatomine\",\"snowpea\",\"chomper\"] },\n  { id:8, title:\"白天 1-9\", sub:\"双发火力\", rows:5, initSun:50, flags:2, night:false, graves:0, zombies:[\"normal\",\"conehead\",\"polevaulter\",\"buckethead\"],\n    plants:[\"sunflower\",\"peashooter\",\"cherrybomb\",\"wallnut\",\"potatomine\",\"snowpea\",\"chomper\",\"repeaterpea\"] },\n  { id:9, title:\"白天 1-10\", sub:\"终极防线\", rows:5, initSun:50, flags:2, night:false, graves:0, zombies:[\"normal\",\"conehead\",\"polevaulter\",\"buckethead\"],\n    plants:DAY_PLANTS_FULL.slice() },\n];\n/* 黑夜 2-1～2-10：无天降阳光、有墓碑；植物按原版解锁进度 */\nconst NIGHT_LEVELS = [\n  { id:0, title:\"黑夜 2-1\", sub:\"小喷菇\", rows:5, initSun:50, flags:1, night:true, graves:5, zombies:[\"normal\",\"newspaper\"],\n    plants:[\"sunflower\",\"puffshroom\",\"snowpea\",\"cherrybomb\",\"wallnut\",\"repeaterpea\"] },\n  { id:1, title:\"黑夜 2-2\", sub:\"阳光菇\", rows:5, initSun:50, flags:2, night:true, graves:6, zombies:[\"normal\",\"newspaper\",\"conehead\",\"buckethead\"],\n    plants:[\"sunshroom\",\"puffshroom\",\"snowpea\",\"cherrybomb\",\"wallnut\",\"repeaterpea\"] },\n  { id:2, title:\"黑夜 2-3\", sub:\"大喷菇\", rows:5, initSun:50, flags:1, night:true, graves:6, zombies:[\"normal\",\"screendoor\",\"conehead\"],\n    plants:[\"sunshroom\",\"puffshroom\",\"fumeshroom\",\"cherrybomb\",\"wallnut\",\"snowpea\"] },\n  { id:3, title:\"黑夜 2-4\", sub:\"墓碑吞噬者\", rows:5, initSun:50, flags:2, night:true, graves:8, zombies:[\"normal\",\"screendoor\",\"conehead\",\"polevaulter\"],\n    plants:[\"sunshroom\",\"puffshroom\",\"fumeshroom\",\"gravebuster\",\"cherrybomb\",\"wallnut\",\"snowpea\"] },\n  { id:4, title:\"黑夜 2-5\", sub:\"黑夜特训\", rows:5, initSun:75, flags:1, night:true, graves:10, zombies:[\"normal\",\"conehead\",\"buckethead\"],\n    plants:[\"sunshroom\",\"puffshroom\",\"fumeshroom\",\"gravebuster\",\"cherrybomb\",\"potatomine\",\"wallnut\"] },\n  { id:5, title:\"黑夜 2-6\", sub:\"橄榄球僵尸\", rows:5, initSun:50, flags:1, night:true, graves:8, zombies:[\"normal\",\"football\",\"conehead\"],\n    plants:[\"sunshroom\",\"puffshroom\",\"fumeshroom\",\"gravebuster\",\"hypnoshroom\",\"cherrybomb\",\"wallnut\"] },\n  { id:6, title:\"黑夜 2-7\", sub:\"胆小菇\", rows:5, initSun:50, flags:2, night:true, graves:9, zombies:[\"normal\",\"football\",\"conehead\",\"screendoor\"],\n    plants:[\"sunshroom\",\"puffshroom\",\"fumeshroom\",\"scaredyshroom\",\"gravebuster\",\"hypnoshroom\",\"cherrybomb\",\"wallnut\"] },\n  { id:7, title:\"黑夜 2-8\", sub:\"舞王僵尸\", rows:5, initSun:50, flags:1, night:true, graves:8, zombies:[\"normal\",\"dancing\",\"conehead\"],\n    plants:[\"sunshroom\",\"puffshroom\",\"fumeshroom\",\"gravebuster\",\"hypnoshroom\",\"iceshroom\",\"cherrybomb\",\"wallnut\"] },\n  { id:8, title:\"黑夜 2-9\", sub:\"毁灭菇\", rows:5, initSun:50, flags:2, night:true, graves:9, zombies:[\"normal\",\"dancing\",\"conehead\",\"screendoor\"],\n    plants:[\"sunshroom\",\"puffshroom\",\"fumeshroom\",\"gravebuster\",\"hypnoshroom\",\"iceshroom\",\"doomshroom\",\"wallnut\",\"cherrybomb\"] },\n  { id:9, title:\"黑夜 2-10\", sub:\"黑夜终章\", rows:5, initSun:50, flags:2, night:true, graves:12, zombies:[\"normal\",\"dancing\",\"conehead\",\"screendoor\",\"newspaper\",\"football\"],\n    plants:NIGHT_PLANTS_FULL.slice() },\n];\nconst CLEAR_DAY_ID = 9;\nconst CLEAR_NIGHT_ID = 9;\nlet curWorld = \"day\"; // day | night\nfunction getWorldLevels(){ return curWorld === \"night\" ? NIGHT_LEVELS : DAY_LEVELS; }\nfunction isNightLevel(){ return !!(curLevelMeta && curLevelMeta.night); }\n\n/* ===== 难度选项 ===== */\nconst DIFFICULTIES = {\n  easy:   { id:\"easy\",   name:\"简单\", color:\"#7ec850\", sunIntervalMul:0.85, volMul:0.7,  speedMul:0.85, hpMul:0.8,  initSunBonus:50 },\n  normal: { id:\"normal\", name:\"普通\", color:\"#e0a030\", sunIntervalMul:1,    volMul:1,    speedMul:1,    hpMul:1,    initSunBonus:0 },\n  hard:   { id:\"hard\",   name:\"困难\", color:\"#e0584c\", sunIntervalMul:1.2,  volMul:1.35, speedMul:1.18, hpMul:1.25, initSunBonus:0 },\n};\nconst DIFF_ORDER = [\"easy\",\"normal\",\"hard\"];\nconst ENDLESS_LEVEL = {\n  id: -1, title:\"无尽模式\", sub:\"能撑多久？\", rows:5, initSun:50, flags:999, night:false, graves:0,\n  zombies:[\"normal\",\"conehead\",\"polevaulter\",\"buckethead\",\"newspaper\",\"football\",\"screendoor\",\"dancing\"],\n  plants:DAY_PLANTS_FULL.concat([\"threepeater\",\"puffshroom\",\"sunshroom\",\"fumeshroom\",\"hypnoshroom\"])\n};\n\n/* ===== 僵尸类型定义 ===== */\nconst ZOMBIE_TYPES = {\n  normal:     { hp: ZOMBIE_HEALTH, helmet: 0 },\n  conehead:   { hp: ZOMBIE_HEALTH, helmet: CONEHEAD_HEALTH },\n  buckethead: { hp: ZOMBIE_HEALTH, helmet: BUCKETHEAD_HEALTH },\n  polevaulter:{ hp: POLE_VAULTER_HEALTH, helmet: 0, speed: 1.5 },\n  flag:       { hp: ZOMBIE_HEALTH, helmet: 0 },\n  newspaper:  { hp: NEWSPAPER_HEALTH, helmet: NEWSPAPER_PAPER_HEALTH, speed: 1.0 },\n  football:   { hp: FOOTBALL_HEALTH, helmet: FOOTBALL_HELMET_HEALTH, speed: 1.6 },\n  screendoor: { hp: SCREENDOOR_HEALTH, helmet: SCREENDOOR_SHIELD_HEALTH, speed: 1.0 },\n  dancing:    { hp: ZOMBIE_HEALTH, helmet: 0, speed: 1.0 },\n  backup:     { hp: 200, helmet: 0, speed: 1.0 },\n};\n\n/* ===== 植物定义（数值源自 pypvz constants.py PLANT_CARD_INFO） ===== */\nconst PLANTS = {\n  sunflower:   { name:\"向日葵\",   cost:50,  cd:7500,  hp:PLANT_HEALTH, color:\"#ffc928\" },\n  peashooter:  { name:\"豌豆射手\", cost:100, cd:7500,  hp:PLANT_HEALTH, color:\"#6cbb3c\" },\n  repeaterpea: { name:\"双发豌豆\", cost:200, cd:7500,  hp:PLANT_HEALTH, color:\"#5aa530\" },\n  snowpea:     { name:\"寒冰射手\", cost:175, cd:7500,  hp:PLANT_HEALTH, color:\"#5ab8e0\" },\n  chomper:     { name:\"食人花\",   cost:150, cd:7500,  hp:PLANT_HEALTH, color:\"#9a5ab8\" },\n  threepeater: { name:\"三线豌豆\", cost:325, cd:7500,  hp:PLANT_HEALTH, color:\"#6cbb3c\" },\n  wallnut:     { name:\"坚果墙\",   cost:50,  cd:30000, hp:WALLNUT_HEALTH, color:\"#c98a3a\" },\n  potatomine:  { name:\"土豆地雷\", cost:25,  cd:30000, hp:PLANT_HEALTH, color:\"#b8862b\" },\n  cherrybomb:  { name:\"樱桃炸弹\", cost:150, cd:50000, hp:Infinity, color:\"#e04444\" },\n  puffshroom:  { name:\"小喷菇\",   cost:0,   cd:7500,  hp:PLANT_HEALTH, color:\"#c8b0e0\" },\n  sunshroom:   { name:\"阳光菇\",   cost:25,  cd:7500,  hp:PLANT_HEALTH, color:\"#e8d060\" },\n  fumeshroom:  { name:\"大喷菇\",   cost:75,  cd:7500,  hp:PLANT_HEALTH, color:\"#7a5aa8\" },\n  gravebuster: { name:\"墓碑吞噬者\", cost:75, cd:7500,  hp:PLANT_HEALTH, color:\"#5a8a4a\" },\n  hypnoshroom: { name:\"魅惑菇\",   cost:75,  cd:30000, hp:PLANT_HEALTH, color:\"#d060c0\" },\n  scaredyshroom:{ name:\"胆小菇\",  cost:25,  cd:7500,  hp:PLANT_HEALTH, color:\"#90c070\" },\n  iceshroom:   { name:\"寒冰菇\",   cost:75,  cd:50000, hp:Infinity, color:\"#70d0f0\" },\n  doomshroom:  { name:\"毁灭菇\",   cost:125, cd:50000, hp:Infinity, color:\"#3a2a4a\" },\n};\nconst CARD_ORDER = Object.keys(PLANTS);\nconst ICE_SHROOM_FREEZE = 4000;\nconst DOOM_DAMAGE = 1800;\nconst DOOM_RANGE = 5; // 以格为单位的切比雪夫半径（约全场大范围）\nconst FUME_RANGE = 4;\nconst PUFF_RANGE = 3;\nconst SUNSHROOM_SMALL = 15;\nconst SUNSHROOM_GROW = 20000;\n\n/* ===== 状态 ===== */\nlet state, lastTime, mouse, selected, shovelActive;\nlet waveTimer, waveIndex, zombiesToSpawn, spawnTimer;\nlet sunDropTimer, suns, bullets, particles, mowerEntities, boomFx, craters, fumeFx = [];\nlet gameSeed, actionLog;\nlet curLevel = 0, curZombies = [\"normal\",\"conehead\"];\nlet gameMode = \"normal\", collectedSun = 0;\nlet curDiff = \"normal\", killCount = 0, bestEndlessWave = 0;\ntry { bestEndlessWave = parseInt(localStorage.getItem(\"pvz_endless_best\")||\"0\")||0; } catch(e){}\nlet lbTab = \"clears\";\nlet paused = false;\nlet curCardOrder = CARD_ORDER;\nlet curLevelMeta = DAY_LEVELS[0];\nlet graves = []; // {x,y}\nlet graveSpawnDone = false;\nconst MAX_SEED_SLOTS = 8;\nlet plantPool = [];\nlet pickSelected = [];\nconst MOWER_SPEED = 480;\nconst overlay = document.getElementById(\"overlay\");\nconst ovTitle = document.getElementById(\"ovTitle\");\nconst ovText = document.getElementById(\"ovText\");\nconst ovBtn = document.getElementById(\"ovBtn\");\nconst ovNextBtn = document.getElementById(\"ovNextBtn\");\nconst ovMenuBtn = document.getElementById(\"ovMenuBtn\");\nconst ovLB = document.getElementById(\"ovLeaderboard\");\n\nfunction hasNextLevel(){\n  if(gameMode !== \"normal\" || curLevel < 0) return false;\n  const list = getWorldLevels();\n  if(curLevel < list.length - 1) return true;\n  // 白天通关后可进黑夜\n  if(curWorld === \"day\" && curLevel === CLEAR_DAY_ID) return true;\n  return false;\n}\nfunction nextLevelTarget(){\n  const list = getWorldLevels();\n  if(curLevel < list.length - 1) return { world: curWorld, id: curLevel + 1, title: list[curLevel + 1].title };\n  if(curWorld === \"day\" && curLevel === CLEAR_DAY_ID) return { world: \"night\", id: 0, title: NIGHT_LEVELS[0].title };\n  return null;\n}\nfunction setOverlayActions(mode){\n  if(mode === \"win\" && hasNextLevel()){\n    const nxt = nextLevelTarget();\n    ovNextBtn.style.display = \"inline-block\";\n    ovNextBtn.textContent = \"下一关 · \" + (nxt.title.replace(/^(白天|黑夜) /,\"\"));\n    ovBtn.textContent = \"再打一局\";\n  } else {\n    ovNextBtn.style.display = \"none\";\n    if(mode === \"win\") ovBtn.textContent = \"再来一局\";\n    else if(mode === \"endless\") ovBtn.textContent = \"再来一局\";\n    else ovBtn.textContent = \"重试\";\n  }\n}\nfunction hasGrave(cx, cy){ return graves.some(g => g.x===cx && g.y===cy); }\nfunction removeGrave(cx, cy){ graves = graves.filter(g => !(g.x===cx && g.y===cy)); }\nfunction spawnGraves(n){\n  graves = [];\n  let tries = 0;\n  while(graves.length < n && tries < 80){\n    tries++;\n    const x = 4 + Math.floor(rng()*5); // 右侧列 4-8\n    const y = Math.floor(rng()*ROWS);\n    if(!hasGrave(x,y)) graves.push({x,y});\n  }\n}\nconst cheatInput = document.getElementById(\"cheatInput\");\nlet sunClickCount = 0;\n\nfunction getDiff(){ return DIFFICULTIES[curDiff] || DIFFICULTIES.normal; }\nfunction isEndless(){ return gameMode === \"endless\"; }\n\n/* 填充结算页排行榜 HTML */\nfunction fillLeaderboardHTML(){\n  const lb = window.__LEADERBOARD__ || [];\n  if(!lb.length){ ovLB.innerHTML = \"\"; ovLB.style.display = \"none\"; return; }\n  ovLB.style.display = \"block\";\n  let rows = lb.map((e,i)=>{\n    const m = i===0?\"🥇\":i===1?\"🥈\":i===2?\"🥉\":(i+1)+\".\";\n    return '<div class=\"lb-row\"><span>'+m+\" \"+e.name+\"</span><span>\"+e.count+\" 次</span></div>\";\n  }).join(\"\");\n  ovLB.innerHTML = \"<h3>通关排行榜</h3>\" + rows + '<div class=\"lb-note\">通关白天 1-10 或黑夜 2-10（普通/困难）记入排行榜</div>';\n}\n\nfunction newGame(seed, levelId, mode, world){\n  gameMode = mode || \"normal\";\n  if(world) curWorld = world;\n  let lv;\n  if(gameMode === \"endless\"){\n    lv = ENDLESS_LEVEL;\n  } else if(gameMode === \"weekly\"){\n    lv = Object.assign({}, DAY_LEVELS[CLEAR_DAY_ID], {\n      title: \"每周挑战\", sub: \"阵容轮换\", night:false, graves:0,\n      plants: ENDLESS_LEVEL.plants.slice()\n    });\n  } else {\n    const list = getWorldLevels();\n    lv = list[levelId !== undefined ? levelId : 0] || list[0];\n  }\n  curLevelMeta = lv;\n  curLevel = (gameMode === \"weekly\") ? CLEAR_DAY_ID : lv.id;\n  curZombies = lv.zombies.slice();\n  if(gameMode === \"weekly\" && window.__WEEK__ && window.__WEEK__.zombies){\n    curZombies = window.__WEEK__.zombies.slice();\n  }\n  plantPool = lv.plants ? lv.plants.slice() : CARD_ORDER.slice();\n  pickSelected = [];\n  curCardOrder = plantPool.length > MAX_SEED_SLOTS ? [] : plantPool.slice();\n  ROWS = lv.rows;\n  GRID_Y = calcGridY(ROWS);\n  const diff = getDiff();\n  INIT_SUN = lv.initSun + (diff.initSunBonus || 0);\n  NUM_FLAGS = isEndless() ? 999 : lv.flags;\n\n  gameSeed = (seed === undefined) ? (Date.now() & 0xffffffff) : seed;\n  rng = makeRng(gameSeed);\n  state = plantPool.length > MAX_SEED_SLOTS ? \"pick\" : \"play\";\n  lastTime = 0;\n  mouse = {x:0, y:0, click:false};\n  selected = null;\n  shovelActive = false;\n  grid = [];\n  for(let y=0;y<ROWS;y++){ grid.push(new Array(COLS).fill(null)); }\n  zombies = []; bullets = []; suns = []; particles = [];\n  boomFx = []; craters = []; fumeFx = [];\n  sun = INIT_SUN;\n  collectedSun = 0;\n  killCount = 0;\n  paused = false;\n  sunDropTimer = 4000;\n  cardCd = {}; CARD_ORDER.forEach(k=>cardCd[k]=0);\n  mowers = new Array(ROWS).fill(true);\n  mowerEntities = [];\n  waveIndex = 0;\n  zombiesToSpawn = [];\n  spawnTimer = 0;\n  waveTimer = isEndless() ? 5000 : 6000;\n  bigWaveWarning = 0;\n  actionLog = [];\n  graveSpawnDone = false;\n  spawnGraves(lv.graves || 0);\n  overlay.classList.remove(\"show\");\n  showGameShell();\n}\nfunction getPickLayout(){\n  const slotW = 64, slotH = 78, slotGap = 8;\n  const slotN = MAX_SEED_SLOTS;\n  const bankW = slotN * slotW + (slotN - 1) * slotGap;\n  const bankX = (W - bankW) / 2;\n  const bankY = 56;\n  const poolCols = 6;\n  const poolCardW = 92, poolCardH = 96, poolGapX = 10, poolGapY = 10;\n  const poolW = poolCols * poolCardW + (poolCols - 1) * poolGapX;\n  const poolX = (W - poolW) / 2;\n  const poolY = 180;\n  const startBtn = { w: 200, h: 48, x: W/2 - 100, y: H - 64 };\n  const backBtn = { w: 120, h: 40, x: 24, y: H - 58 };\n  return { slotW, slotH, slotGap, bankX, bankY, poolCols, poolCardW, poolCardH, poolGapX, poolGapY, poolX, poolY, startBtn, backBtn };\n}\nfunction confirmPickAndStart(){\n  if(pickSelected.length < 1) return;\n  curCardOrder = pickSelected.slice();\n  selected = null;\n  shovelActive = false;\n  state = \"play\";\n  waveTimer = isEndless() ? 5000 : 6000;\n}\nlet grid, zombies, sun, cardCd, bigWaveWarning;\n\n/* ===== 波次生成（参考 pypvz level.py createWaves） ===== */\nfunction buildWave(n){\n  const diff = getDiff();\n  let vol = Math.floor(n*0.8/2)+1;\n  let big = (n % 10 === 0);\n  if(big) vol = Math.floor(vol*2.5);\n  if(isEndless()){\n    vol = Math.floor(vol * (1 + Math.min(n, 80) * 0.02));\n    if(n >= 15){\n      [\"newspaper\",\"football\",\"screendoor\"].forEach(k=>{\n        if(!curZombies.includes(k)) curZombies.push(k);\n      });\n    }\n  }\n  vol = Math.max(1, Math.floor(vol * diff.volMul));\n  let list = [];\n  if(big) list.push(\"flag\");\n  for(let i=list.length;i<vol;i++){\n    const r = rng();\n    if(curZombies.includes(\"football\") && n >= (isEndless()?8:5) && r < 0.14 + Math.min(n,40)*0.003){\n      list.push(\"football\");\n    } else if(curZombies.includes(\"buckethead\") && n >= 5 && r < 0.15){\n      list.push(\"buckethead\");\n    } else if(curZombies.includes(\"screendoor\") && n >= 4 && r < 0.16){\n      list.push(\"screendoor\");\n    } else if(curZombies.includes(\"polevaulter\") && n >= 3 && r < 0.25){\n      list.push(\"polevaulter\");\n    } else if(curZombies.includes(\"newspaper\") && n >= 3 && r < 0.18){\n      list.push(\"newspaper\");\n    } else if(curZombies.includes(\"conehead\") && n >= 3 && r < Math.min(0.15 + n*0.03, 0.45)){\n      list.push(\"conehead\");\n    } else {\n      list.push(\"normal\");\n    }\n  }\n  return list;\n}\n\n/* ===== 坐标转换 ===== */\nfunction cellAt(px, py){\n  const cx = Math.floor((px-GRID_X)/CELL_W);\n  const cy = Math.floor((py-GRID_Y)/CELL_H);\n  if(cx<0||cx>=COLS||cy<0||cy>=ROWS) return null;\n  return {x:cx, y:cy};\n}\nfunction cellCenter(cx, cy){\n  return { x: GRID_X + cx*CELL_W + CELL_W/2, y: GRID_Y + cy*CELL_H + CELL_H/2 };\n}\n\n/* ===== 绘制：草地背景 ===== */\nfunction drawBackground(){\n  const night = isNightLevel() || (state===\"menu\" && curWorld===\"night\");\n  const lawnX = GRID_X, lawnY = GRID_Y, lawnW = COLS*CELL_W, lawnH = ROWS*CELL_H;\n\n  /* 顶栏 */\n  const barGrad = ctx.createLinearGradient(0,0,0,GRID_Y-20);\n  if(night){ barGrad.addColorStop(0,\"#121a28\"); barGrad.addColorStop(1,\"#1c2a3c\"); }\n  else { barGrad.addColorStop(0,\"#6f4a24\"); barGrad.addColorStop(1,\"#8b5a2b\"); }\n  ctx.fillStyle = barGrad;\n  ctx.fillRect(0, 0, W, GRID_Y-20);\n\n  /* 左侧房屋区：保持比例，底对齐，不再纵向拉扁 */\n  const houseBg = ctx.createLinearGradient(0, GRID_Y, GRID_X, GRID_Y);\n  if(night){\n    houseBg.addColorStop(0,\"#182030\"); houseBg.addColorStop(0.65,\"#243428\"); houseBg.addColorStop(1,\"#2a4030\");\n  } else {\n    houseBg.addColorStop(0,\"#9ecf6a\"); houseBg.addColorStop(0.55,\"#b8e07a\"); houseBg.addColorStop(1,\"#a8d96e\");\n  }\n  ctx.fillStyle = houseBg;\n  ctx.fillRect(0, GRID_Y, GRID_X, ROWS*CELL_H);\n  /* 树篱暗示 */\n  ctx.fillStyle = night ? \"rgba(20,40,28,.45)\" : \"rgba(60,120,40,.22)\";\n  for(let i=0;i<6;i++){\n    const bx = 8 + (i%3)*28;\n    const by = GRID_Y + 30 + Math.floor(i/3)* (ROWS*CELL_H*0.35);\n    ctx.beginPath(); ctx.ellipse(bx, by, 22, 34, 0, 0, 7); ctx.fill();\n  }\n  if(houseReady && houseImg){\n    ctx.save();\n    ctx.beginPath();\n    ctx.rect(0, GRID_Y, GRID_X, ROWS*CELL_H);\n    ctx.clip();\n    const maxW = GRID_X - 6;\n    const maxH = ROWS * CELL_H - 10;\n    const iw = houseImg.naturalWidth || houseImg.width;\n    const ih = houseImg.naturalHeight || houseImg.height;\n    let dw = maxW;\n    let dh = dw * (ih / Math.max(1, iw));\n    if(dh > maxH){\n      dh = maxH;\n      dw = dh * (iw / Math.max(1, ih));\n    }\n    const hx = Math.max(2, (GRID_X - dw) / 2);\n    const hy = GRID_Y + ROWS*CELL_H - dh - 2;\n    ctx.imageSmoothingEnabled = true;\n    ctx.imageSmoothingQuality = \"high\";\n    ctx.drawImage(houseImg, hx, hy, dw, dh);\n    if(night){\n      ctx.fillStyle = \"rgba(8,14,28,.32)\";\n      ctx.fillRect(0, GRID_Y, GRID_X, ROWS*CELL_H);\n    }\n    ctx.restore();\n  } else {\n    ctx.fillStyle = night ? \"#4a3a2a\" : \"#c4915a\";\n    ctx.fillRect(28, GRID_Y+ROWS*CELL_H*0.28, 70, ROWS*CELL_H*0.55);\n    ctx.fillStyle = night ? \"#2e2418\" : \"#a86a3a\";\n    ctx.beginPath();\n    ctx.moveTo(20, GRID_Y+ROWS*CELL_H*0.32);\n    ctx.lineTo(63, GRID_Y+ROWS*CELL_H*0.18);\n    ctx.lineTo(106, GRID_Y+ROWS*CELL_H*0.32);\n    ctx.closePath(); ctx.fill();\n    ctx.fillStyle = night ? \"#1a140e\" : \"#7a4a28\";\n    ctx.fillRect(52, GRID_Y+ROWS*CELL_H-48, 26, 34);\n  }\n\n  /* 草坪贴图 */\n  const lawnTex = night\n    ? (nightLawnReady ? nightLawnImg : null)\n    : (dayLawnReady ? dayLawnImg : null);\n  if(lawnTex){\n    ctx.save();\n    ctx.beginPath(); ctx.rect(lawnX, lawnY, lawnW, lawnH); ctx.clip();\n    ctx.drawImage(lawnTex, lawnX, lawnY, lawnW, lawnH);\n    for(let y=0;y<ROWS;y++){\n      ctx.fillStyle = night\n        ? ((y%2===0) ? \"rgba(0,0,0,.12)\" : \"rgba(255,255,255,.04)\")\n        : ((y%2===0) ? \"rgba(40,90,20,.10)\" : \"rgba(255,255,220,.07)\");\n      ctx.fillRect(lawnX, lawnY+y*CELL_H, lawnW, CELL_H);\n    }\n    /* 轻微纵向景深 */\n    const depth = ctx.createLinearGradient(0, lawnY, 0, lawnY+lawnH);\n    depth.addColorStop(0, night ? \"rgba(8,14,24,.18)\" : \"rgba(255,245,200,.10)\");\n    depth.addColorStop(1, night ? \"rgba(0,0,0,.22)\" : \"rgba(30,70,20,.12)\");\n    ctx.fillStyle = depth;\n    ctx.fillRect(lawnX, lawnY, lawnW, lawnH);\n    ctx.restore();\n  } else {\n    for(let y=0;y<ROWS;y++){\n      if(night) ctx.fillStyle = (y%2===0) ? \"#2a4a34\" : \"#23402c\";\n      else ctx.fillStyle = (y%2===0) ? \"#a8d96e\" : \"#b4e07a\";\n      ctx.fillRect(lawnX, lawnY+y*CELL_H, lawnW, CELL_H);\n    }\n  }\n  ctx.strokeStyle = night ? \"rgba(180,210,200,.10)\" : \"rgba(40,80,20,.12)\";\n  ctx.lineWidth = 1;\n  for(let x=0;x<=COLS;x++){\n    ctx.beginPath();\n    ctx.moveTo(lawnX+x*CELL_W, lawnY);\n    ctx.lineTo(lawnX+x*CELL_W, lawnY+lawnH);\n    ctx.stroke();\n  }\n  for(let y=0;y<=ROWS;y++){\n    ctx.beginPath();\n    ctx.moveTo(lawnX, lawnY+y*CELL_H);\n    ctx.lineTo(lawnX+lawnW, lawnY+y*CELL_H);\n    ctx.stroke();\n  }\n\n  /* 墓碑 */\n  if(Array.isArray(graves)){\n    for(const g of graves){\n      const cx = lawnX + g.x*CELL_W + CELL_W/2;\n      const cy = lawnY + g.y*CELL_H + CELL_H/2 + 10;\n      ctx.fillStyle = \"rgba(0,0,0,.28)\";\n      ctx.beginPath(); ctx.ellipse(cx, cy+18, 16, 5, 0, 0, 7); ctx.fill();\n      const gg = ctx.createLinearGradient(cx-14, cy-34, cx+14, cy+16);\n      gg.addColorStop(0,\"#8a919c\"); gg.addColorStop(0.55,\"#5c636e\"); gg.addColorStop(1,\"#3a4048\");\n      ctx.fillStyle = gg;\n      ctx.beginPath(); ctx.roundRect(cx-15, cy-32, 30, 44, 8); ctx.fill();\n      ctx.strokeStyle = \"rgba(255,255,255,.12)\"; ctx.lineWidth = 1;\n      ctx.stroke();\n      ctx.fillStyle = \"#2a2e34\";\n      ctx.fillRect(cx-17, cy+10, 34, 6);\n      ctx.fillStyle = \"rgba(220,230,240,.55)\";\n      ctx.font = \"bold 10px sans-serif\"; ctx.textAlign = \"center\";\n      ctx.fillText(\"RIP\", cx, cy-6);\n      ctx.strokeStyle = \"rgba(200,210,220,.35)\"; ctx.lineWidth = 1.5;\n      ctx.beginPath(); ctx.moveTo(cx, cy-22); ctx.lineTo(cx, cy-12);\n      ctx.moveTo(cx-4, cy-18); ctx.lineTo(cx+4, cy-18); ctx.stroke();\n    }\n  }\n\n  if(night){\n    const veil = ctx.createLinearGradient(lawnX, lawnY, lawnX+lawnW, lawnY);\n    veil.addColorStop(0,\"rgba(10,18,28,.18)\");\n    veil.addColorStop(0.55,\"rgba(8,14,24,.08)\");\n    veil.addColorStop(1,\"rgba(20,40,70,.28)\");\n    ctx.fillStyle = veil;\n    ctx.fillRect(lawnX, lawnY, lawnW, lawnH);\n    ctx.fillStyle = \"rgba(210,225,240,.85)\";\n    ctx.beginPath(); ctx.arc(W-54, lawnY+28, 18, 0, 7); ctx.fill();\n    ctx.fillStyle = \"rgba(210,225,240,.12)\";\n    ctx.beginPath(); ctx.arc(W-54, lawnY+28, 34, 0, 7); ctx.fill();\n    ctx.fillStyle = \"rgba(8,14,24,.35)\";\n    ctx.beginPath(); ctx.arc(W-46, lawnY+24, 13, 0, 7); ctx.fill();\n    for(let i=0;i<18;i++){\n      const sx = lawnX + ((i*97)%lawnW);\n      const sy = lawnY + ((i*53)%Math.max(1,lawnH-20));\n      ctx.fillStyle = \"rgba(230,240,255,\"+(0.15+((i%3)*0.08))+\")\";\n      ctx.fillRect(sx, sy, 1.5, 1.5);\n    }\n  }\n\n  for(let y=0;y<ROWS;y++){\n    if(!mowers[y]) continue;\n    const my = GRID_Y + y*CELL_H + CELL_H/2;\n    drawMowerBody(GRID_X-26, my);\n  }\n}\n\n/* 割草机车身 */\nfunction drawMowerBody(x, cy){\n  ctx.fillStyle = \"rgba(0,0,0,.18)\";\n  ctx.beginPath(); ctx.ellipse(x+18, cy+18, 18, 5, 0, 0, 7); ctx.fill();\n  if(mowerReady && mowerImg){\n    const mw = 46, mh = 40;\n    ctx.drawImage(mowerImg, x - 4, cy - mh + 18, mw, mh);\n    return;\n  }\n  ctx.fillStyle = \"#9aa0a6\";\n  ctx.fillRect(x, cy-12, 22, 22);\n  ctx.fillStyle = \"#7a8086\";\n  ctx.fillRect(x+3, cy-15, 16, 6);\n  ctx.strokeStyle = \"#5f6368\"; ctx.lineWidth = 2;\n  ctx.beginPath(); ctx.moveTo(x+19, cy-12); ctx.lineTo(x+26, cy-16); ctx.stroke();\n  ctx.fillStyle = \"#c0c4c8\";\n  ctx.fillRect(x-4, cy-4, 6, 14);\n  ctx.strokeStyle = \"#5f6368\"; ctx.lineWidth = 1;\n  for(let i=0;i<3;i++){\n    ctx.beginPath(); ctx.moveTo(x-4, cy-4+i*5); ctx.lineTo(x+2, cy-4+i*5); ctx.stroke();\n  }\n  ctx.fillStyle = \"#3a3d42\";\n  ctx.beginPath(); ctx.arc(x+6, cy+10, 5, 0, 7); ctx.fill();\n  ctx.beginPath(); ctx.arc(x+16, cy+10, 5, 0, 7); ctx.fill();\n  ctx.fillStyle = \"#8a8e92\";\n  ctx.beginPath(); ctx.arc(x+6, cy+10, 2, 0, 7); ctx.fill();\n  ctx.beginPath(); ctx.arc(x+16, cy+10, 2, 0, 7); ctx.fill();\n}\n\n/* ===== 绘制：植物（自绘矢量，不使用外部精灵图） ===== */\nfunction drawPlant(p, cx, cy){\n  const t = p.type;\n  ctx.save();\n  ctx.translate(cx, cy);\n  const bob = Math.sin(p.anim*0.004 + p.cx*0.7)*2;\n  ctx.translate(0, bob);\n  if(t===\"sunflower\") drawSunflower(p);\n  else if(t===\"peashooter\") drawPeashooter(p);\n  else if(t===\"repeaterpea\") drawRepeater(p);\n  else if(t===\"snowpea\") drawSnowPea(p);\n  else if(t===\"chomper\") drawChomper(p);\n  else if(t===\"threepeater\") drawThreepeater(p);\n  else if(t===\"wallnut\") drawWallnut(p);\n  else if(t===\"potatomine\") drawPotato(p);\n  else if(t===\"cherrybomb\") drawCherry(p);\n  else if(t===\"puffshroom\") drawPuffShroom(p);\n  else if(t===\"sunshroom\") drawSunShroom(p);\n  else if(t===\"fumeshroom\") drawFumeShroom(p);\n  else if(t===\"gravebuster\") drawGraveBuster(p);\n  else if(t===\"hypnoshroom\") drawHypnoShroom(p);\n  else if(t===\"scaredyshroom\") drawScaredyShroom(p);\n  else if(t===\"iceshroom\") drawIceShroom(p);\n  else if(t===\"doomshroom\") drawDoomShroom(p);\n  ctx.restore();\n  /* 引信阶段显示爆炸范围 */\n  if((t===\"doomshroom\" || t===\"cherrybomb\") && p.fuse != null && p.fuse > 0){\n    const cellR = t===\"doomshroom\" ? DOOM_RANGE : 1.5;\n    const pulse = 0.25 + 0.2 * Math.sin((p.anim||0) * 0.02);\n    ctx.save();\n    ctx.strokeStyle = t===\"doomshroom\"\n      ? (\"rgba(180,40,220,\" + (0.45 + pulse) + \")\")\n      : (\"rgba(255,80,60,\" + (0.4 + pulse) + \")\");\n    ctx.fillStyle = t===\"doomshroom\"\n      ? (\"rgba(120,20,160,\" + (0.08 + pulse * 0.08) + \")\")\n      : (\"rgba(255,60,40,\" + (0.07 + pulse * 0.06) + \")\");\n    ctx.lineWidth = 2;\n    const rw = CELL_W * cellR * 2;\n    const rh = CELL_H * cellR * 2;\n    ctx.beginPath();\n    ctx.roundRect(cx - rw/2, cy - rh/2, rw, rh, 10);\n    ctx.fill(); ctx.stroke();\n    ctx.restore();\n  }\n  const def = PLANTS[t];\n  if(def && p.hp < def.hp && isFinite(def.hp)){\n    const w = 44, hpf = p.hp/def.hp;\n    ctx.fillStyle = \"rgba(0,0,0,.35)\";\n    ctx.fillRect(cx-w/2, cy-36, w, 4);\n    ctx.fillStyle = hpf>0.5?\"#7ec850\":(hpf>0.25?\"#f0a830\":\"#e0584c\");\n    ctx.fillRect(cx-w/2, cy-36, w*hpf, 4);\n  }\n}\nfunction drawSunflower(p){\n  const glow = p.sunTimer != null && p.sunTimer < 1500;\n  ctx.strokeStyle = \"#5a8a2a\"; ctx.lineWidth = 5;\n  ctx.beginPath(); ctx.moveTo(0,20); ctx.lineTo(0,36); ctx.stroke();\n  if(p.bounceT > 0){ ctx.translate(0, -Math.sin((1-p.bounceT/300)*Math.PI)*8); }\n  const r = 18;\n  if(glow){\n    const pulse = 0.6 + Math.sin(p.anim*0.02)*0.4;\n    const gg = ctx.createRadialGradient(0,-6,4,0,-6,30);\n    gg.addColorStop(0, \"rgba(255,240,150,\"+(0.55*pulse)+\")\");\n    gg.addColorStop(1, \"rgba(255,240,150,0)\");\n    ctx.fillStyle = gg;\n    ctx.beginPath(); ctx.arc(0,-6,30,0,7); ctx.fill();\n  }\n  ctx.fillStyle = glow ? \"#ffe066\" : \"#ffc928\";\n  for(let i=0;i<8;i++){\n    const a = i*Math.PI/4 + p.anim*0.0008;\n    ctx.beginPath();\n    ctx.ellipse(Math.cos(a)*r, Math.sin(a)*r - 6, 7, 11, a, 0, 7);\n    ctx.fill();\n  }\n  ctx.fillStyle = glow ? \"#d9a030\" : \"#8b5a2b\";\n  ctx.beginPath(); ctx.arc(0,-6,12,0,7); ctx.fill();\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-4,-8,2,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(4,-8,2,0,7); ctx.fill();\n  ctx.strokeStyle = \"#3a2a1a\"; ctx.lineWidth = 1.5;\n  ctx.beginPath(); ctx.arc(0,-4,3,0.1,Math.PI-0.1); ctx.stroke();\n}\nfunction drawPeashooter(p){\n  ctx.strokeStyle = \"#5a8a2a\"; ctx.lineWidth = 5;\n  ctx.beginPath(); ctx.moveTo(-2,16); ctx.lineTo(-2,34); ctx.stroke();\n  ctx.fillStyle = \"#6cbb3c\";\n  ctx.beginPath(); ctx.ellipse(-12,24,7,4,-0.5,0,7); ctx.fill();\n  ctx.fillStyle = \"#6cbb3c\";\n  ctx.beginPath(); ctx.arc(0,-2,15,0,7); ctx.fill();\n  ctx.fillStyle = \"#4a9a2c\";\n  ctx.beginPath(); ctx.ellipse(14,-4,7,5,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#2a6a1c\";\n  ctx.beginPath(); ctx.arc(18,-4,3,0,7); ctx.fill();\n  ctx.fillStyle = \"#fff\";\n  ctx.beginPath(); ctx.arc(-2,-6,4,0,7); ctx.fill();\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-1,-6,2,0,7); ctx.fill();\n}\nfunction drawRepeater(p){\n  ctx.strokeStyle = \"#3a7a1a\"; ctx.lineWidth = 5;\n  ctx.beginPath(); ctx.moveTo(-2,16); ctx.lineTo(-2,34); ctx.stroke();\n  ctx.fillStyle = \"#5aa530\";\n  ctx.beginPath(); ctx.ellipse(-12,24,7,4,-0.5,0,7); ctx.fill();\n  ctx.fillStyle = \"#4a9a2c\";\n  ctx.beginPath(); ctx.arc(-6,-4,13,0,7); ctx.fill();\n  ctx.fillStyle = \"#5aa530\";\n  ctx.beginPath(); ctx.arc(0,-2,15,0,7); ctx.fill();\n  ctx.fillStyle = \"#4a8a1c\";\n  ctx.beginPath(); ctx.ellipse(14,-4,8,5,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#2a5a0c\";\n  ctx.beginPath(); ctx.arc(18,-4,3.5,0,7); ctx.fill();\n  ctx.fillStyle = \"#fff\";\n  ctx.beginPath(); ctx.arc(-2,-6,4,0,7); ctx.fill();\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-1,-6,2,0,7); ctx.fill();\n}\nfunction drawSnowPea(p){\n  ctx.strokeStyle = \"#3a8a8a\"; ctx.lineWidth = 5;\n  ctx.beginPath(); ctx.moveTo(-2,16); ctx.lineTo(-2,34); ctx.stroke();\n  ctx.fillStyle = \"#5ab8e0\";\n  ctx.beginPath(); ctx.ellipse(-12,24,7,4,-0.5,0,7); ctx.fill();\n  ctx.fillStyle = \"#5ab8e0\";\n  ctx.beginPath(); ctx.arc(0,-2,15,0,7); ctx.fill();\n  ctx.fillStyle = \"#4a9ac0\";\n  ctx.beginPath(); ctx.ellipse(14,-4,7,5,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#2a6a8a\";\n  ctx.beginPath(); ctx.arc(18,-4,3,0,7); ctx.fill();\n  ctx.fillStyle = \"#fff\";\n  ctx.beginPath(); ctx.arc(-2,-6,4,0,7); ctx.fill();\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-1,-6,2,0,7); ctx.fill();\n  ctx.fillStyle = \"rgba(180,230,255,.4)\";\n  ctx.beginPath(); ctx.arc(-4,-8,3,0,7); ctx.fill();\n}\nfunction drawChomper(p){\n  ctx.strokeStyle = \"#5a8a2a\"; ctx.lineWidth = 5;\n  ctx.beginPath(); ctx.moveTo(0,16); ctx.lineTo(0,34); ctx.stroke();\n  ctx.fillStyle = \"#6cbb3c\";\n  ctx.beginPath(); ctx.ellipse(-12,24,7,4,-0.5,0,7); ctx.fill();\n  ctx.beginPath(); ctx.ellipse(12,24,7,4,0.5,0,7); ctx.fill();\n  const openRaw = p.chewing ? (Math.sin(p.anim*0.012)*0.08+0.05) : (Math.sin(p.anim*0.003)*0.15+0.45);\n  const open = Math.max(0.01, openRaw);\n  const belly = p.chewing ? (Math.sin(p.anim*0.008)*2+3) : 0;\n  ctx.fillStyle = \"#b85a8a\";\n  ctx.beginPath(); ctx.ellipse(0,2+belly*0.3,18+belly*0.5,12+belly*0.8,0,0,Math.PI); ctx.fill();\n  ctx.fillStyle = \"#d870b8\";\n  ctx.beginPath(); ctx.ellipse(0,-6,18,14,0,Math.PI,Math.PI*2); ctx.fill();\n  ctx.fillStyle = \"#8a2a4a\";\n  ctx.beginPath(); ctx.ellipse(0,-2,14,8*open,0,0,Math.PI*open); ctx.fill();\n  if(!p.chewing){\n    ctx.fillStyle = \"#fff\";\n    for(let i=0;i<5;i++){\n      const tx = -10+i*5;\n      ctx.beginPath();\n      ctx.moveTo(tx, -4); ctx.lineTo(tx+3, -4); ctx.lineTo(tx+1.5, -4+5*open);\n      ctx.fill();\n    }\n    for(let i=0;i<4;i++){\n      const tx = -8+i*5;\n      ctx.beginPath();\n      ctx.moveTo(tx, 0); ctx.lineTo(tx+3, 0); ctx.lineTo(tx+1.5, 0-4*open);\n      ctx.fill();\n    }\n  }\n  if(p.chewing){\n    ctx.fillStyle = \"rgba(100,180,255,.8)\";\n    const sweat = Math.sin(p.anim*0.006)*1.5;\n    ctx.beginPath(); ctx.ellipse(-13,-17+sweat,2.5,4,0,0,7); ctx.fill();\n    ctx.beginPath(); ctx.ellipse(13,-17+sweat,2.5,4,0,0,7); ctx.fill();\n  }\n  if(p.chewing){\n    ctx.strokeStyle = \"#3a2a1a\"; ctx.lineWidth = 2;\n    ctx.beginPath(); ctx.arc(-8,-14,4,0.2,Math.PI-0.2); ctx.stroke();\n    ctx.beginPath(); ctx.arc(8,-14,4,0.2,Math.PI-0.2); ctx.stroke();\n  } else {\n    ctx.fillStyle = \"#fff\";\n    ctx.beginPath(); ctx.arc(-8,-14,4,0,7); ctx.fill();\n    ctx.beginPath(); ctx.arc(8,-14,4,0,7); ctx.fill();\n    ctx.fillStyle = \"#3a2a1a\";\n    ctx.beginPath(); ctx.arc(-7,-13,2,0,7); ctx.fill();\n    ctx.beginPath(); ctx.arc(9,-13,2,0,7); ctx.fill();\n    ctx.fillStyle = \"rgba(255,255,255,.8)\";\n    ctx.beginPath(); ctx.arc(-6,-14,0.8,0,7); ctx.fill();\n    ctx.beginPath(); ctx.arc(10,-14,0.8,0,7); ctx.fill();\n  }\n  ctx.strokeStyle = \"#d870b8\"; ctx.lineWidth = 2;\n  ctx.beginPath();\n  ctx.moveTo(0,-18); ctx.quadraticCurveTo(-4,-24,-8,-22);\n  ctx.stroke();\n  ctx.beginPath();\n  ctx.moveTo(0,-18); ctx.quadraticCurveTo(4,-24,8,-22);\n  ctx.stroke();\n  ctx.fillStyle = \"#e890c8\";\n  ctx.beginPath(); ctx.arc(-8,-22,2,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(8,-22,2,0,7); ctx.fill();\n}\nfunction drawThreepeater(p){\n  /* 茎 + 对称底叶 */\n  ctx.strokeStyle = \"#5a8a2a\"; ctx.lineWidth = 5;\n  ctx.beginPath(); ctx.moveTo(0,18); ctx.lineTo(0,34); ctx.stroke();\n  ctx.fillStyle = \"#5aa530\";\n  ctx.beginPath(); ctx.ellipse(-11,28,7,4,-0.5,0,7); ctx.fill();\n  ctx.beginPath(); ctx.ellipse(11,28,7,4,0.5,0,7); ctx.fill();\n  /* 三个头垂直堆叠，各带豌豆射手炮口与眼睛 */\n  const heads = [{y:-14,r:8.5},{y:-2,r:9.5},{y:10,r:8.5}];\n  for(const h of heads){\n    const hx = -3;\n    ctx.fillStyle = \"#6cbb3c\";\n    ctx.beginPath(); ctx.arc(hx, h.y, h.r, 0, 7); ctx.fill();\n    ctx.fillStyle = \"#5aa530\";\n    ctx.beginPath(); ctx.arc(hx, h.y+h.r*0.45, h.r*0.85, 0.2, Math.PI-0.2); ctx.fill();\n    ctx.fillStyle = \"#4a9a2c\";\n    ctx.beginPath(); ctx.ellipse(hx+h.r-1, h.y, 5, h.r*0.55, 0, 0, 7); ctx.fill();\n    ctx.fillStyle = \"#2a6a1c\";\n    ctx.beginPath(); ctx.arc(hx+h.r+2, h.y, 2.2, 0, 7); ctx.fill();\n    ctx.fillStyle = \"#fff\";\n    ctx.beginPath(); ctx.arc(hx-2, h.y-2.5, 2.3, 0, 7); ctx.fill();\n    ctx.fillStyle = \"#3a2a1a\";\n    ctx.beginPath(); ctx.arc(hx-1.2, h.y-2.5, 1.1, 0, 7); ctx.fill();\n  }\n  /* 头间小叶片点缀 */\n  ctx.fillStyle = \"#7acb4c\";\n  ctx.beginPath(); ctx.ellipse(-3,-8,3.5,2,0,0,7); ctx.fill();\n  ctx.beginPath(); ctx.ellipse(-3,4,3.5,2,0,0,7); ctx.fill();\n}\nfunction drawWallnut(p){\n  const f = p.hp/WALLNUT_HEALTH;\n  ctx.fillStyle = \"#c98a3a\";\n  ctx.beginPath(); ctx.ellipse(0,4,18,22,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#b87a2a\";\n  ctx.beginPath(); ctx.ellipse(0,14,14,10,0,0,7); ctx.fill();\n  ctx.fillStyle = \"rgba(255,220,160,.25)\";\n  ctx.beginPath(); ctx.ellipse(-6,-6,6,8,-0.3,0,7); ctx.fill();\n  if(f<=0.66){\n    ctx.strokeStyle = \"#7a4a1a\"; ctx.lineWidth = 1.8;\n    ctx.beginPath(); ctx.moveTo(-9,-8); ctx.lineTo(-5,0); ctx.lineTo(-8,8); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(-3,-10); ctx.lineTo(-1,-2); ctx.stroke();\n  }\n  if(f<=0.33){\n    ctx.fillStyle = \"#5a3a1a\";\n    ctx.beginPath(); ctx.ellipse(10,-2,8,10,0.3,0,7); ctx.fill();\n    ctx.strokeStyle = \"#5a3010\"; ctx.lineWidth = 2;\n    ctx.beginPath(); ctx.moveTo(6,-10); ctx.lineTo(2,2); ctx.lineTo(8,10); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(-10,2); ctx.lineTo(-4,6); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(0,-12); ctx.lineTo(-3,-4); ctx.stroke();\n  }\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-5,-2,2,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(5,-2,2,0,7); ctx.fill();\n  ctx.strokeStyle = \"#3a2a1a\"; ctx.lineWidth = 1.5;\n  if(f>0.66){\n    ctx.beginPath(); ctx.arc(0,4,4,0.1,Math.PI-0.1); ctx.stroke();\n  } else if(f>0.33){\n    ctx.beginPath(); ctx.moveTo(-3,6); ctx.lineTo(3,6); ctx.stroke();\n  } else {\n    ctx.beginPath(); ctx.ellipse(0,7,3,2,0,0,7); ctx.fill();\n    ctx.strokeStyle = \"#3a2a1a\";\n    ctx.beginPath(); ctx.arc(-5,-4,3,Math.PI+0.3,Math.PI*2-0.3); ctx.stroke();\n    ctx.beginPath(); ctx.arc(5,-4,3,Math.PI+0.3,Math.PI*2-0.3); ctx.stroke();\n  }\n}\nfunction drawPotato(p){\n  if(!p.armed){\n    ctx.fillStyle = \"#8b6a3a\";\n    ctx.beginPath(); ctx.ellipse(0,16,16,8,0,0,Math.PI); ctx.fill();\n    ctx.fillStyle = \"#b8862b\";\n    ctx.beginPath(); ctx.ellipse(0,16,16,8,0,Math.PI,0); ctx.fill();\n    ctx.strokeStyle = \"#5a3a1a\"; ctx.lineWidth = 2;\n    ctx.beginPath(); ctx.moveTo(0,12); ctx.quadraticCurveTo(4,2,10,0); ctx.stroke();\n    return;\n  }\n  ctx.fillStyle = \"#b8862b\";\n  ctx.beginPath(); ctx.ellipse(0,8,16,14,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#a8761b\";\n  ctx.beginPath(); ctx.ellipse(0,14,12,8,0,0,7); ctx.fill();\n  ctx.strokeStyle = \"#5a3a1a\"; ctx.lineWidth = 2;\n  ctx.beginPath(); ctx.moveTo(0,-6); ctx.lineTo(6,-14); ctx.stroke();\n  const sp = 3 + Math.sin(p.anim*0.02)*2;\n  ctx.fillStyle = \"#ff8c42\";\n  ctx.beginPath(); ctx.arc(6,-14,sp,0,7); ctx.fill();\n  ctx.fillStyle = \"#ffe066\";\n  ctx.beginPath(); ctx.arc(6,-14,sp*0.5,0,7); ctx.fill();\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-4,4,2,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(4,4,2,0,7); ctx.fill();\n}\nfunction drawCherry(p){\n  const blink = Math.sin(p.anim*0.01)>0;\n  ctx.fillStyle = \"#e04444\";\n  ctx.beginPath(); ctx.arc(-8,2,13,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(8,2,13,0,7); ctx.fill();\n  ctx.fillStyle = \"#c03434\";\n  ctx.beginPath(); ctx.arc(-8,8,9,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(8,8,9,0,7); ctx.fill();\n  ctx.strokeStyle = \"#5a3a1a\"; ctx.lineWidth = 2;\n  ctx.beginPath(); ctx.moveTo(0,-10); ctx.quadraticCurveTo(6,-18,12,-20); ctx.stroke();\n  if(blink){\n    ctx.fillStyle = \"#3a2a1a\";\n    ctx.beginPath(); ctx.arc(-10,-2,1.5,0,7); ctx.fill();\n    ctx.beginPath(); ctx.arc(6,-2,1.5,0,7); ctx.fill();\n  }\n}\nfunction drawPuffShroom(p){\n  ctx.fillStyle = \"#c8b0e0\";\n  ctx.beginPath(); ctx.ellipse(0,6,12,10,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#a890c8\";\n  ctx.beginPath(); ctx.ellipse(0,-2,16,12,0,Math.PI,0); ctx.fill();\n  ctx.fillStyle = \"#fff\";\n  ctx.beginPath(); ctx.arc(-5,-2,2.5,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(5,-2,2.5,0,7); ctx.fill();\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-4,-2,1.2,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(6,-2,1.2,0,7); ctx.fill();\n}\nfunction drawSunShroom(p){\n  const big = !!p.grown;\n  const s = big ? 1.25 : 1;\n  ctx.fillStyle = big ? \"#e8d060\" : \"#d8c050\";\n  ctx.beginPath(); ctx.ellipse(0,6*s,11*s,9*s,0,0,7); ctx.fill();\n  ctx.fillStyle = big ? \"#f0e080\" : \"#e0d060\";\n  ctx.beginPath(); ctx.ellipse(0,-2*s,14*s,11*s,0,Math.PI,0); ctx.fill();\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-4*s,-2*s,1.5*s,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(4*s,-2*s,1.5*s,0,7); ctx.fill();\n}\nfunction drawFumeShroom(p){\n  if(p.puffT > 0){\n    const k = Math.sin((1 - p.puffT / 260) * Math.PI);\n    ctx.translate(-k * 3, 0);\n    ctx.scale(1 + k * 0.08, 1 - k * 0.06);\n  }\n  ctx.fillStyle = \"#7a5aa8\";\n  ctx.beginPath(); ctx.ellipse(0,8,16,12,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#9a7ac8\";\n  ctx.beginPath(); ctx.ellipse(0,-4,20,16,0,Math.PI,0); ctx.fill();\n  ctx.fillStyle = \"#5a3a88\";\n  ctx.beginPath(); ctx.ellipse(14,-2,8,5,0,0,7); ctx.fill();\n  ctx.fillStyle = \"rgba(180,140,220,.45)\";\n  ctx.beginPath(); ctx.ellipse(22,-2,10,6,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#fff\";\n  ctx.beginPath(); ctx.arc(-6,-6,3,0,7); ctx.fill();\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-5,-6,1.5,0,7); ctx.fill();\n}\nfunction drawGraveBuster(p){\n  ctx.fillStyle = \"#5a8a4a\";\n  ctx.beginPath(); ctx.ellipse(0,10,14,8,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#7aaa5a\";\n  ctx.beginPath(); ctx.arc(0,-2,12,0,7); ctx.fill();\n  ctx.strokeStyle = \"#3a5a2a\"; ctx.lineWidth = 2;\n  ctx.beginPath(); ctx.moveTo(-8,4); ctx.lineTo(-14,16); ctx.stroke();\n  ctx.beginPath(); ctx.moveTo(8,4); ctx.lineTo(14,16); ctx.stroke();\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-4,-4,2,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(4,-4,2,0,7); ctx.fill();\n  if(p.eatTimer != null){\n    ctx.fillStyle = \"rgba(255,255,255,.7)\";\n    ctx.font = \"10px sans-serif\"; ctx.textAlign = \"center\";\n    ctx.fillText(Math.ceil(p.eatTimer/1000)+\"s\", 0, -20);\n  }\n}\nfunction drawHypnoShroom(p){\n  ctx.fillStyle = \"#d060c0\";\n  ctx.beginPath(); ctx.ellipse(0,6,13,10,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#e080d0\";\n  ctx.beginPath(); ctx.ellipse(0,-4,16,13,0,Math.PI,0); ctx.fill();\n  const spin = (p.anim||0)*0.01;\n  ctx.strokeStyle = \"#fff\"; ctx.lineWidth = 1.5;\n  ctx.beginPath(); ctx.arc(0,-4,6,spin,spin+4); ctx.stroke();\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-5,-4,1.5,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(5,-4,1.5,0,7); ctx.fill();\n}\nfunction drawScaredyShroom(p){\n  if(p.hiding){\n    ctx.fillStyle = \"#6a9050\";\n    ctx.beginPath(); ctx.ellipse(0,14,10,6,0,0,7); ctx.fill();\n    return;\n  }\n  ctx.fillStyle = \"#90c070\";\n  ctx.beginPath(); ctx.ellipse(0,8,12,10,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#a8d088\";\n  ctx.beginPath(); ctx.ellipse(0,-6,14,16,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#fff\";\n  ctx.beginPath(); ctx.arc(-4,-8,3,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(4,-8,3,0,7); ctx.fill();\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-3,-8,1.4,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(5,-8,1.4,0,7); ctx.fill();\n}\nfunction drawIceShroom(p){\n  ctx.fillStyle = \"#70d0f0\";\n  ctx.beginPath(); ctx.ellipse(0,4,16,12,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#a0e8ff\";\n  ctx.beginPath(); ctx.ellipse(0,-6,18,14,0,Math.PI,0); ctx.fill();\n  ctx.fillStyle = \"rgba(255,255,255,.5)\";\n  ctx.beginPath(); ctx.arc(-6,-8,4,0,7); ctx.fill();\n}\nfunction drawDoomShroom(p){\n  const fuseOn = p.fuse != null && p.fuse > 0;\n  const pulse = 0.5+Math.sin((p.anim||0)*(fuseOn?0.04:0.02))*0.5;\n  if(fuseOn){\n    ctx.fillStyle = \"rgba(255,80,40,\"+(0.25+pulse*0.35)+\")\";\n    ctx.beginPath(); ctx.arc(0,-2,26+pulse*6,0,7); ctx.fill();\n  }\n  ctx.fillStyle = \"#3a2a4a\";\n  ctx.beginPath(); ctx.ellipse(0,6,18,14,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#5a3a6a\";\n  ctx.beginPath(); ctx.ellipse(0,-6,22,16,0,Math.PI,0); ctx.fill();\n  ctx.fillStyle = fuseOn ? \"#ff3030\" : \"#e04444\";\n  ctx.beginPath(); ctx.arc(0,-4,4+pulse*2,0,7); ctx.fill();\n  ctx.fillStyle = \"rgba(224,68,68,\"+(0.3*pulse)+\")\";\n  ctx.beginPath(); ctx.arc(0,-4,14,0,7); ctx.fill();\n}\n\n/* ===== 绘制：僵尸 ===== */\nfunction drawZombie(z){\n  const cx = z.x, cy = z.y;\n  ctx.save();\n  ctx.translate(cx, cy);\n  /* 撑杆跳跳跃动画 */\n  if(z.jumping){\n    const jp = z.jumpProgress || 0;\n    ctx.translate(0, -Math.sin(jp*Math.PI)*30);\n  }\n  const walk = Math.sin(z.anim*0.008)*3;\n  ctx.fillStyle = \"rgba(0,0,0,.18)\";\n  ctx.beginPath(); ctx.ellipse(0,30,16,5,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#7a8b5a\";\n  ctx.fillRect(-8, 14+walk, 6, 14);\n  ctx.fillRect(2, 14-walk, 6, 14);\n  ctx.fillStyle = \"#8a9b6a\";\n  ctx.beginPath(); ctx.roundRect(-11, -6, 22, 22, 5); ctx.fill();\n  ctx.fillStyle = \"#9aab7a\";\n  ctx.fillRect(-16, 0, 8, 6);\n  ctx.fillRect(8, 0, 8, 6);\n  ctx.fillStyle = \"#b5c098\";\n  ctx.beginPath(); ctx.arc(0, -16, 12, 0, 7); ctx.fill();\n  ctx.fillStyle = \"#5a4a3a\";\n  ctx.beginPath(); ctx.arc(0,-22,12,Math.PI*1.1,Math.PI*1.9); ctx.fill();\n  ctx.fillStyle = \"#fff\";\n  ctx.beginPath(); ctx.arc(-4,-17,3,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(4,-17,3,0,7); ctx.fill();\n  ctx.fillStyle = \"#c0342a\";\n  ctx.beginPath(); ctx.arc(-4,-17,1.5,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(4,-17,1.5,0,7); ctx.fill();\n  ctx.fillStyle = \"#3a1a1a\";\n  ctx.fillRect(-4,-10,8,3);\n  ctx.fillStyle = \"#eee\";\n  ctx.fillRect(-3,-10,2,2); ctx.fillRect(1,-10,2,2);\n  /* 路障 */\n  if(z.kind === \"conehead\" && z.helmet > 0){\n    const hf = z.helmet / z.maxHelmet;\n    ctx.fillStyle = \"#e8822a\";\n    ctx.beginPath();\n    ctx.moveTo(-10, -24); ctx.lineTo(10, -24); ctx.lineTo(0, -43);\n    ctx.closePath(); ctx.fill();\n    ctx.fillStyle = \"#c46818\";\n    ctx.fillRect(-10, -25, 20, 3);\n    ctx.fillStyle = \"rgba(255,255,255,.55)\";\n    ctx.fillRect(-7, -31, 14, 3);\n    ctx.fillRect(-5, -37, 10, 2.5);\n    if(hf < 0.6){\n      ctx.strokeStyle = \"rgba(80,40,10,.7)\"; ctx.lineWidth = 1.2;\n      ctx.beginPath(); ctx.moveTo(-4,-26); ctx.lineTo(2,-33); ctx.lineTo(-2,-39); ctx.stroke();\n    }\n    if(hf < 0.3){\n      ctx.beginPath(); ctx.moveTo(5,-28); ctx.lineTo(-1,-35); ctx.stroke();\n    }\n  }\n  /* 铁桶 */\n  if(z.kind === \"buckethead\" && z.helmet > 0){\n    const hf = z.helmet / z.maxHelmet;\n    ctx.fillStyle = \"#888\";\n    ctx.fillRect(-12, -30, 24, 20);\n    ctx.fillStyle = \"#aaa\";\n    ctx.fillRect(-12, -30, 24, 4);\n    ctx.fillStyle = \"#666\";\n    ctx.fillRect(-12, -14, 24, 4);\n    ctx.fillStyle = \"rgba(255,255,255,.2)\";\n    ctx.fillRect(-9, -28, 4, 16);\n    if(hf < 0.6){\n      ctx.strokeStyle = \"rgba(40,40,40,.6)\"; ctx.lineWidth = 1.5;\n      ctx.beginPath(); ctx.moveTo(-6,-26); ctx.lineTo(2,-18); ctx.stroke();\n    }\n    if(hf < 0.3){\n      ctx.beginPath(); ctx.moveTo(6,-28); ctx.lineTo(-2,-16); ctx.stroke();\n      ctx.beginPath(); ctx.moveTo(-8,-20); ctx.lineTo(0,-14); ctx.stroke();\n    }\n  }\n  /* 撑杆跳杆子 */\n  if(z.kind === \"polevaulter\" && z.hasPole){\n    ctx.strokeStyle = \"#8b5a2b\"; ctx.lineWidth = 3;\n    ctx.beginPath();\n    ctx.moveTo(-18, 10); ctx.quadraticCurveTo(-30, -20, -10, -35);\n    ctx.stroke();\n  }\n  /* 旗帜 */\n  if(z.kind===\"flag\"){\n    ctx.strokeStyle = \"#8b5a2b\"; ctx.lineWidth = 2;\n    ctx.beginPath(); ctx.moveTo(12,-28); ctx.lineTo(12,-6); ctx.stroke();\n    ctx.fillStyle = \"#e04444\";\n    const fw = 14 + Math.sin(z.anim*0.01)*3;\n    ctx.beginPath();\n    ctx.moveTo(12,-28); ctx.lineTo(12+fw,-24); ctx.lineTo(12,-18);\n    ctx.closePath(); ctx.fill();\n  }\n  /* 读报僵尸：报纸盾 / 狂暴表情 */\n  if(z.kind === \"newspaper\"){\n    if(z.helmet > 0){\n      ctx.fillStyle = \"#f5f0e0\";\n      ctx.fillRect(-15, -8, 20, 24);\n      ctx.strokeStyle = \"#c0b890\"; ctx.lineWidth = 1;\n      ctx.strokeRect(-15, -8, 20, 24);\n      ctx.fillStyle = \"#5a4a3a\";\n      ctx.fillRect(-13, -5, 16, 1.5);\n      for(let i=0;i<5;i++){ ctx.fillRect(-13, -1+i*4, 16, 0.8); }\n    } else {\n      ctx.fillStyle = \"#c0342a\";\n      ctx.beginPath(); ctx.arc(-4,-17,2.2,0,7); ctx.fill();\n      ctx.beginPath(); ctx.arc(4,-17,2.2,0,7); ctx.fill();\n      ctx.strokeStyle = \"#c0342a\"; ctx.lineWidth = 1.6;\n      ctx.beginPath(); ctx.moveTo(-7,-21); ctx.lineTo(-2,-19); ctx.stroke();\n      ctx.beginPath(); ctx.moveTo(7,-21); ctx.lineTo(2,-19); ctx.stroke();\n      if(Math.floor(z.anim/150)%2 === 0){\n        ctx.fillStyle = \"#e04444\";\n        ctx.font = \"bold 14px sans-serif\"; ctx.textAlign = \"center\";\n        ctx.fillText(\"!\", 13, -22);\n      }\n    }\n  }\n  /* 橄榄球僵尸：头盔 + 护甲 */\n  if(z.kind === \"football\"){\n    ctx.fillStyle = \"#3a5a3a\";\n    ctx.beginPath(); ctx.roundRect(-14, -8, 28, 22, 5); ctx.fill();\n    if(z.helmet > 0){\n      const hf = z.helmet / z.maxHelmet;\n      ctx.fillStyle = \"#4a3a2a\";\n      ctx.beginPath(); ctx.ellipse(0, -22, 14, 11, 0, Math.PI, 0); ctx.fill();\n      ctx.fillStyle = \"#d8b020\";\n      ctx.fillRect(-13, -20, 26, 3);\n      ctx.strokeStyle = \"#1a1a1a\"; ctx.lineWidth = 1.2;\n      ctx.beginPath(); ctx.moveTo(-9,-22); ctx.lineTo(9,-22); ctx.stroke();\n      for(let i=-2;i<=2;i++){ ctx.beginPath(); ctx.moveTo(i*4,-26); ctx.lineTo(i*4,-18); ctx.stroke(); }\n      ctx.fillStyle = \"rgba(0,0,0,.25)\";\n      ctx.fillRect(-12, -28, 4, 8);\n      if(hf < 0.5){\n        ctx.strokeStyle = \"rgba(20,20,20,.6)\"; ctx.lineWidth = 1.5;\n        ctx.beginPath(); ctx.moveTo(-6,-24); ctx.lineTo(4,-18); ctx.stroke();\n      }\n    }\n  }\n  /* 铁网门僵尸：铁网门盾（挡在前方左侧，迎向豌豆） */\n  if(z.kind === \"screendoor\" && z.helmet > 0){\n    const hf = z.helmet / z.maxHelmet;\n    ctx.fillStyle = \"#9a9a9a\";\n    ctx.fillRect(-18, -26, 12, 48);\n    ctx.fillStyle = \"#7a7a7a\";\n    ctx.fillRect(-18, -26, 12, 4);\n    ctx.fillRect(-18, 18, 12, 4);\n    ctx.strokeStyle = \"#4a4a4a\"; ctx.lineWidth = 0.7;\n    for(let i=1;i<6;i++){ ctx.beginPath(); ctx.moveTo(-18, -26+i*8); ctx.lineTo(-6, -26+i*8); ctx.stroke(); }\n    for(let i=1;i<2;i++){ ctx.beginPath(); ctx.moveTo(-18+i*6, -26); ctx.lineTo(-18+i*6, 22); ctx.stroke(); }\n    ctx.beginPath(); ctx.moveTo(-12, -26); ctx.lineTo(-12, 22); ctx.stroke();\n    if(hf < 0.5){\n      ctx.strokeStyle = \"rgba(40,40,40,.6)\"; ctx.lineWidth = 1.2;\n      ctx.beginPath(); ctx.moveTo(-16,-18); ctx.lineTo(-8,2); ctx.stroke();\n    }\n  }\n  /* 舞王帽子 */\n  if(z.kind === \"dancing\"){\n    ctx.fillStyle = \"#2a2a2a\";\n    ctx.beginPath(); ctx.ellipse(0, -26, 14, 6, 0, 0, 7); ctx.fill();\n    ctx.fillStyle = \"#e04444\";\n    ctx.fillRect(-10, -34, 20, 8);\n    ctx.fillStyle = \"#fff\";\n    ctx.font = \"bold 10px sans-serif\"; ctx.textAlign = \"center\";\n    ctx.fillText(\"♪\", 0, -26);\n  }\n  if(z.kind === \"backup\"){\n    ctx.fillStyle = \"#c04080\";\n    ctx.beginPath(); ctx.roundRect(-11, -6, 22, 22, 5); ctx.fill();\n  }\n  /* 魅惑（我方） */\n  if(z.hypno){\n    ctx.fillStyle = \"rgba(208,96,192,.4)\";\n    ctx.beginPath(); ctx.roundRect(-17, -28, 34, 54, 8); ctx.fill();\n    ctx.fillStyle = \"#e080d0\";\n    ctx.font = \"bold 12px sans-serif\"; ctx.textAlign = \"center\";\n    ctx.fillText(\"♥\", 0, -34);\n  }\n  /* 减速冰冻效果 */\n  if(z.frozen > 0){\n    ctx.fillStyle = \"rgba(140,220,255,.55)\";\n    ctx.beginPath(); ctx.roundRect(-17, -28, 34, 54, 8); ctx.fill();\n  } else if(z.slowed > 0){\n    ctx.fillStyle = \"rgba(90,184,224,.35)\";\n    ctx.beginPath(); ctx.roundRect(-17, -28, 34, 54, 8); ctx.fill();\n    ctx.fillStyle = \"rgba(180,230,255,.7)\";\n    ctx.beginPath(); ctx.arc(-12, -10, 2, 0, 7); ctx.fill();\n    ctx.beginPath(); ctx.arc(10, -5, 1.5, 0, 7); ctx.fill();\n    ctx.beginPath(); ctx.arc(8, 15, 2, 0, 7); ctx.fill();\n    ctx.beginPath(); ctx.arc(-10, 20, 1.5, 0, 7); ctx.fill();\n    ctx.beginPath(); ctx.arc(0, -22, 1.8, 0, 7); ctx.fill();\n  }\n  ctx.restore();\n  /* 防具血条 */\n  if(z.maxHelmet > 0 && z.helmet > 0){\n    const w = 28, hf = z.helmet/z.maxHelmet;\n    ctx.fillStyle = \"rgba(0,0,0,.4)\";\n    ctx.fillRect(cx-w/2, cy-52, w, 3.5);\n    ctx.fillStyle = (z.kind===\"buckethead\"||z.kind===\"football\"||z.kind===\"screendoor\") ? \"#aaa\" : (z.kind===\"newspaper\" ? \"#d8c8a0\" : \"#e8822a\");\n    ctx.fillRect(cx-w/2, cy-52, w*hf, 3.5);\n  }\n  /* 本体血条 */\n  const maxHp = ZOMBIE_TYPES[z.kind] ? ZOMBIE_TYPES[z.kind].hp : ZOMBIE_HEALTH;\n  if(z.hp < maxHp && !(z.maxHelmet > 0 && z.helmet > 0)){\n    const w = 30, hpf = z.hp/maxHp;\n    ctx.fillStyle = \"rgba(0,0,0,.35)\";\n    ctx.fillRect(cx-w/2, cy-38, w, 4);\n    ctx.fillStyle = hpf>0.5?\"#7ec850\":(hpf>0.25?\"#f0a830\":\"#e0584c\");\n    ctx.fillRect(cx-w/2, cy-38, w*hpf, 4);\n  }\n}\n\n/* ===== 绘制：阳光 ===== */\nfunction drawSun(s){\n  const r = 20;\n  const pulse = 1 + Math.sin(s.anim*0.006)*0.08;\n  const g = ctx.createRadialGradient(s.x,s.y,2,s.x,s.y,r*pulse*1.6);\n  g.addColorStop(0,\"rgba(255,230,120,.7)\");\n  g.addColorStop(1,\"rgba(255,230,120,0)\");\n  ctx.fillStyle = g;\n  ctx.beginPath(); ctx.arc(s.x,s.y,r*pulse*1.6,0,7); ctx.fill();\n  ctx.fillStyle = \"#ffd24a\";\n  ctx.beginPath(); ctx.arc(s.x,s.y,r*pulse,0,7); ctx.fill();\n  ctx.fillStyle = \"#ffe89a\";\n  ctx.beginPath(); ctx.arc(s.x-3,s.y-3,r*pulse*0.5,0,7); ctx.fill();\n  ctx.strokeStyle = \"rgba(255,210,74,.6)\"; ctx.lineWidth = 2;\n  for(let i=0;i<8;i++){\n    const a = i*Math.PI/4 + s.anim*0.002;\n    ctx.beginPath();\n    ctx.moveTo(s.x+Math.cos(a)*r*pulse, s.y+Math.sin(a)*r*pulse);\n    ctx.lineTo(s.x+Math.cos(a)*(r+5)*pulse, s.y+Math.sin(a)*(r+5)*pulse);\n    ctx.stroke();\n  }\n}\n\n/* ===== 绘制：子弹 ===== */\nfunction drawBullet(b){\n  if(b.spore){\n    const r = b.puff ? 4.5 : 5.5;\n    const wob = Math.sin((b.anim||0)*0.03 + b.x*0.05) * 0.8;\n    ctx.fillStyle = \"rgba(190,140,230,.35)\";\n    ctx.beginPath(); ctx.arc(b.x-6, b.y+wob, r*0.9, 0, 7); ctx.fill();\n    ctx.fillStyle = \"rgba(200,160,240,.45)\";\n    ctx.beginPath(); ctx.arc(b.x, b.y+wob, r+2.5, 0, 7); ctx.fill();\n    ctx.fillStyle = b.puff ? \"#b57ae0\" : \"#c78ad8\";\n    ctx.beginPath(); ctx.arc(b.x, b.y+wob, r, 0, 7); ctx.fill();\n    ctx.fillStyle = \"#eedcff\";\n    ctx.beginPath(); ctx.arc(b.x-1.5, b.y-1.5+wob, r*0.35, 0, 7); ctx.fill();\n  } else if(b.ice){\n    ctx.fillStyle = \"rgba(90,184,224,.4)\";\n    ctx.beginPath(); ctx.arc(b.x,b.y,7,0,7); ctx.fill();\n    ctx.fillStyle = \"#5ab8e0\";\n    ctx.beginPath(); ctx.arc(b.x,b.y,5,0,7); ctx.fill();\n    ctx.fillStyle = \"#b0e8ff\";\n    ctx.beginPath(); ctx.arc(b.x-1,b.y-1,2,0,7); ctx.fill();\n  } else {\n    ctx.fillStyle = \"rgba(108,187,60,.4)\";\n    ctx.beginPath(); ctx.arc(b.x,b.y,7,0,7); ctx.fill();\n    ctx.fillStyle = \"#7ec850\";\n    ctx.beginPath(); ctx.arc(b.x,b.y,5,0,7); ctx.fill();\n    ctx.fillStyle = \"#a8e07a\";\n    ctx.beginPath(); ctx.arc(b.x-1,b.y-1,2,0,7); ctx.fill();\n  }\n}\n\n/* ===== 绘制：粒子 ===== */\nfunction drawParticle(p){\n  ctx.globalAlpha = p.life/p.maxLife;\n  ctx.fillStyle = p.color;\n  ctx.beginPath(); ctx.arc(p.x,p.y,p.size,0,7); ctx.fill();\n  ctx.globalAlpha = 1;\n}\n\n/* ===== 卡片布局（按植物数量自适应） ===== */\nfunction getCardLayout(){\n  const n = curCardOrder.length;\n  const cardY = 8, cardH = 78, gap = 4;\n  const rightReserve = 200;\n  const maxW = Math.min(58, Math.floor((W - rightReserve - 24 - (n+1)*gap) / (n + 0.8)));\n  const cardW = Math.max(42, maxW);\n  return { cardX0: 12, cardY, cardW, cardH, gap };\n}\n\n/* ===== 绘制：UI ===== */\nfunction drawUI(now){\n  const { cardX0, cardY, cardW, cardH, gap } = getCardLayout();\n  curCardOrder.forEach((key, i)=>{\n    const def = PLANTS[key];\n    const x = cardX0 + i*(cardW+gap);\n    const cdLeft = Math.max(0, cardCd[key] - now);\n    const affordable = sun >= def.cost;\n    const onCd = cdLeft > 0;\n    const sel = selected===key;\n    ctx.fillStyle = sel ? \"#fff6d0\" : \"#f7e8c8\";\n    ctx.strokeStyle = sel ? \"#e0a030\" : \"#c9a878\";\n    ctx.lineWidth = sel ? 3 : 1.5;\n    ctx.shadowColor = sel ? \"rgba(224,160,48,.45)\" : \"rgba(0,0,0,.12)\";\n    ctx.shadowBlur = sel ? 8 : 3; ctx.shadowOffsetY = 2;\n    ctx.beginPath(); ctx.roundRect(x, cardY, cardW, cardH, 8); ctx.fill(); ctx.stroke();\n    ctx.shadowColor = \"transparent\"; ctx.shadowBlur = 0; ctx.shadowOffsetY = 0;\n    ctx.save();\n    ctx.translate(x+cardW/2, cardY+24);\n    const sc = Math.min(0.48, cardW/102);\n    ctx.scale(sc, sc);\n    drawPlantIcon(key, now, i);\n    ctx.restore();\n    ctx.textAlign = \"center\";\n    ctx.fillStyle = affordable ? \"#6a5744\" : \"#a05048\";\n    const nameFs = cardW < 48 ? 8 : 9;\n    ctx.font = nameFs + \"px sans-serif\";\n    let pname = def.name || \"\";\n    while(pname.length > 1 && ctx.measureText(pname).width > cardW - 6){\n      pname = pname.slice(0, -1);\n    }\n    if(pname !== def.name) pname = pname.slice(0, Math.max(1, pname.length - 1)) + \"…\";\n    ctx.fillText(pname, x+cardW/2, cardY+cardH-18);\n    ctx.fillStyle = affordable ? \"#5a4a3a\" : \"#c0342a\";\n    ctx.font = \"bold 11px sans-serif\";\n    ctx.fillText(def.cost, x+cardW/2, cardY+cardH-5);\n    if(onCd){\n      const cdFrac = cdLeft / def.cd;\n      ctx.fillStyle = \"rgba(40,40,40,.55)\";\n      ctx.beginPath(); ctx.roundRect(x, cardY, cardW, cardH*cdFrac, 8); ctx.fill();\n    }\n    if(!affordable && !onCd){\n      ctx.fillStyle = \"rgba(80,80,80,.28)\";\n      ctx.beginPath(); ctx.roundRect(x, cardY, cardW, cardH, 8); ctx.fill();\n    }\n  });\n  const shX = cardX0 + curCardOrder.length*(cardW+gap) + 6;\n  ctx.save();\n  ctx.translate(shX+22, cardY+30);\n  if(shovelActive){ ctx.scale(1.12,1.12); }\n  ctx.fillStyle = shovelActive ? \"#fff3c4\" : \"#efe0c0\";\n  ctx.strokeStyle = shovelActive ? \"#e0a030\" : \"#8b5a2b\"; ctx.lineWidth = 2;\n  ctx.beginPath(); ctx.roundRect(-18, -28, 40, 56, 8); ctx.fill(); ctx.stroke();\n  ctx.strokeStyle = \"#8b5a2b\"; ctx.lineWidth = 4;\n  ctx.beginPath(); ctx.moveTo(-6,-14); ctx.lineTo(6,16); ctx.stroke();\n  ctx.fillStyle = shovelActive ? \"#ffd24a\" : \"#c9a878\";\n  ctx.beginPath(); ctx.moveTo(-12,-18); ctx.lineTo(12,-18); ctx.lineTo(10,-8); ctx.lineTo(-10,-8); ctx.closePath(); ctx.fill();\n  ctx.restore();\n  const sx = W - 130;\n  const sunGrad = ctx.createLinearGradient(sx, cardY, sx, cardY+36);\n  sunGrad.addColorStop(0,\"#fff8d8\"); sunGrad.addColorStop(1,\"#ffe8a0\");\n  ctx.fillStyle = sunGrad;\n  ctx.strokeStyle = \"#8b5a2b\"; ctx.lineWidth = 2;\n  ctx.beginPath(); ctx.roundRect(sx, cardY, 114, 36, 10); ctx.fill(); ctx.stroke();\n  ctx.fillStyle = \"#ffd24a\";\n  ctx.beginPath(); ctx.arc(sx+20, cardY+18, 11, 0, 7); ctx.fill();\n  ctx.fillStyle = \"#ffe89a\";\n  ctx.beginPath(); ctx.arc(sx+17, cardY+15, 4, 0, 7); ctx.fill();\n  ctx.fillStyle = \"#8b5a2b\";\n  ctx.font = \"bold 18px sans-serif\"; ctx.textAlign = \"left\";\n  ctx.fillText(sun, sx+40, cardY+24);\n  const pbX = W-260, pbY = cardY+44, pbW = 240, pbH = 22;\n  ctx.fillStyle = \"#4a3224\";\n  ctx.beginPath(); ctx.roundRect(pbX, pbY, pbW, pbH, 8); ctx.fill();\n  if(isEndless()){\n    const cycle = 10;\n    const prog = (waveIndex % cycle) / cycle;\n    const g = ctx.createLinearGradient(pbX,0,pbX+pbW,0);\n    g.addColorStop(0,\"#e8822a\"); g.addColorStop(1,\"#e04444\");\n    ctx.fillStyle = g;\n    ctx.beginPath(); ctx.roundRect(pbX+2, pbY+2, Math.max(4,(pbW-4)*prog), pbH-4, 6); ctx.fill();\n    ctx.fillStyle = \"#fff\"; ctx.font = \"bold 11px sans-serif\"; ctx.textAlign = \"center\";\n    ctx.fillText(\"第 \" + waveIndex + \" 波 · 击杀 \" + killCount, pbX+pbW/2, pbY+15);\n  } else {\n    const totalWaves = Math.max(1, NUM_FLAGS*10);\n    const prog = Math.min(waveIndex/totalWaves, 1);\n    ctx.fillStyle = \"#7ec850\";\n    ctx.beginPath(); ctx.roundRect(pbX+2, pbY+2, (pbW-4)*prog, pbH-4, 6); ctx.fill();\n    for(let f=1; f<=NUM_FLAGS; f++){\n      const fx = pbX + (pbW * f*10/totalWaves);\n      ctx.fillStyle = f*10<=waveIndex ? \"#e04444\" : \"#fff\";\n      ctx.beginPath(); ctx.moveTo(fx, pbY-2); ctx.lineTo(fx+10, pbY+3); ctx.lineTo(fx, pbY+8); ctx.closePath(); ctx.fill();\n    }\n    ctx.fillStyle = \"#fff\"; ctx.font = \"11px sans-serif\"; ctx.textAlign = \"center\";\n    ctx.fillText(\"进度 \" + waveIndex + \"/\" + totalWaves, pbX+pbW/2, pbY+15);\n  }\n  const d = getDiff();\n  ctx.fillStyle = \"#ffd24a\"; ctx.font = \"bold 12px sans-serif\"; ctx.textAlign = \"left\";\n  const modeLabel = isEndless() ? \"无尽模式\" : (gameMode===\"weekly\" ? \"每周挑战\" : curLevelMeta.title);\n  ctx.fillText(modeLabel + \" · \" + d.name, 14, cardY+cardH+14);\n  if(isEndless() && bestEndlessWave > 0){\n    ctx.fillStyle = \"rgba(255,255,255,.75)\"; ctx.font = \"11px sans-serif\";\n    ctx.fillText(\"历史最佳 \" + bestEndlessWave + \" 波\", 14, cardY+cardH+28);\n  }\n  if(bigWaveWarning > 0){\n    ctx.fillStyle = \"rgba(200,40,40,\"+Math.min(bigWaveWarning/2000,0.5)+\")\";\n    ctx.fillRect(0,0,W,H);\n    if(bigWaveWarning > 1500){\n      ctx.fillStyle = \"#fff\";\n      ctx.font = \"bold 28px sans-serif\"; ctx.textAlign=\"center\";\n      ctx.fillText(\"一大波僵尸来袭\", W/2, H/2);\n    }\n  }\n  if(!paused){\n    const p = PAUSE_BTN;\n    const hover = mouse.x>=p.x&&mouse.x<=p.x+p.w&&mouse.y>=p.y&&mouse.y<=p.y+p.h;\n    ctx.fillStyle = hover ? \"#fff3c4\" : \"#f4e4c8\";\n    ctx.strokeStyle = \"#8b5a2b\"; ctx.lineWidth = 2;\n    ctx.beginPath(); ctx.roundRect(p.x, p.y, p.w, p.h, 8); ctx.fill(); ctx.stroke();\n    ctx.fillStyle = \"#8b5a2b\";\n    ctx.fillRect(p.x+12, p.y+10, 5, 16);\n    ctx.fillRect(p.x+23, p.y+10, 5, 16);\n  }\n}\n\n/* ===== 更新逻辑 ===== */\nfunction update(dt, now){\n  if(state !== \"play\" || paused) return;\n  /* 黑夜无天降阳光 */\n  if(!isNightLevel()){\n    sunDropTimer -= dt;\n    if(sunDropTimer <= 0){\n      sunDropTimer = SUN_DROP_INTERVAL * getDiff().sunIntervalMul * (0.7 + rng()*0.6);\n      const sx = GRID_X + 30 + rng()*(COLS*CELL_W-60);\n      suns.push({x:sx, y:-20, ty: GRID_Y + 40 + rng()*(ROWS*CELL_H-80), anim:now, life:SUN_LIVE_TIME, falling:true, value:SUN_VALUE});\n    }\n  }\n  for(let i=suns.length-1;i>=0;i--){\n    const s = suns[i];\n    s.anim = now;\n    if(s.flying){\n      s.flyT += dt;\n      const t = Math.min(s.flyT/s.flyDur, 1);\n      const ease = 1 - Math.pow(1-t, 3);\n      s.x = s.fromX + (s.toX - s.fromX) * ease;\n      s.y = s.fromY + (s.toY - s.fromY) * ease - Math.sin(t*Math.PI)*50;\n      if(t >= 1){\n        const v = s.value != null ? s.value : SUN_VALUE;\n        sun += v;\n        collectedSun += v;\n        actionLog.push({t:performance.now(), e:\"sun\"});\n        spawnParticle(s.toX, s.toY, \"#ffd24a\", 6);\n        suns.splice(i,1);\n      }\n    } else if(s.bouncing){\n      s.vy += s.g * dt;\n      s.y += s.vy * dt;\n      if(s.y >= s.ty){\n        s.y = s.ty;\n        if(s.bounced < 1 && s.vy > 0.12){\n          s.vy = -s.vy * 0.4;\n          s.bounced++;\n        } else {\n          s.bouncing = false;\n          s.vy = 0;\n        }\n      }\n      s.life -= dt;\n      if(s.life <= 0) suns.splice(i,1);\n    } else {\n      if(s.falling){\n        if(s.y < s.ty) s.y += 40*dt/1000;\n        else { s.y = s.ty; s.falling = false; }\n      }\n      s.life -= dt;\n      if(s.life <= 0) suns.splice(i,1);\n    }\n  }\n  const maxWaves = isEndless() ? Infinity : NUM_FLAGS*10;\n  if(zombiesToSpawn.length === 0 && waveIndex < maxWaves){\n    waveTimer -= dt;\n    if(waveTimer <= 0){\n      waveIndex++;\n      zombiesToSpawn = buildWave(waveIndex);\n      if(waveIndex % 10 === 0) bigWaveWarning = 2500;\n      const gapScale = isEndless() ? Math.max(0.55, 1 - waveIndex*0.008) : 1;\n      waveTimer = ((waveIndex % 10 === 0) ? 22000 : (12000 + rng()*6000)) * gapScale;\n      spawnTimer = 0;\n    }\n  } else if(zombiesToSpawn.length > 0){\n    spawnTimer -= dt;\n    if(spawnTimer <= 0){\n      const kind = zombiesToSpawn.shift();\n      const row = Math.floor(rng()*ROWS);\n      const cy = GRID_Y + row*CELL_H + CELL_H/2 + 6;\n      const zt = ZOMBIE_TYPES[kind] || ZOMBIE_TYPES.normal;\n      const diff = getDiff();\n      const endlessScale = isEndless() ? (1 + Math.min(waveIndex, 60) * 0.012) : 1;\n      const hpMul = diff.hpMul * endlessScale;\n      zombies.push({\n        x: SPAWN_X + rng()*30, y: cy, row:row, kind:kind,\n        hp: Math.round(zt.hp * hpMul),\n        helmet: Math.round(zt.helmet * hpMul),\n        maxHelmet: Math.round(zt.helmet * hpMul),\n        speedMul: diff.speedMul * (isEndless() ? (1 + Math.min(waveIndex, 50)*0.006) : 1),\n        anim: now, walkT:0, attackT:0, attackTarget:null, dead:false,\n        hasPole: kind===\"polevaulter\", jumping:false, jumpProgress:0,\n        slowed: 0, enraged: false\n      });\n      spawnTimer = Math.max(280, (600 + rng()*800) * (isEndless() ? Math.max(0.45, 1 - waveIndex*0.01) : 1));\n    }\n  }\n  if(bigWaveWarning > 0) bigWaveWarning -= dt;\n\n  /* 植物更新 */\n  for(let y=0;y<ROWS;y++){\n    for(let x=0;x<COLS;x++){\n      const p = grid[y][x];\n      if(!p) continue;\n      p.anim = now;\n      if(p.bounceT) p.bounceT = Math.max(0, p.bounceT - dt);\n      if(p.type === \"sunflower\"){\n        p.sunTimer -= dt;\n        if(p.sunTimer <= 0){\n          p.sunTimer = SUNFLOWER_INTERVAL;\n          p.bounceT = 300;\n          const ox = (rng()-0.5)*40;\n          suns.push({x:p.cx+ox, y:p.cy-15, ty:p.cy+20, vy:-0.38, g:0.0014, bounced:0, anim:now, life:SUN_LIVE_TIME, falling:false, bouncing:true});\n        }\n      } else if(p.type === \"peashooter\"){\n        let hasZ = false;\n        for(const z of zombies){ if(z.row===y && !z.dead && !z.hypno && z.x > p.cx){ hasZ=true; break; } }\n        if(hasZ){\n          p.shootTimer -= dt;\n          if(p.shootTimer <= 0){\n            p.shootTimer = PEA_INTERVAL;\n            bullets.push({x:p.cx+18, y:p.cy-6, row:y, dmg:BULLET_DAMAGE, anim:now});\n          }\n        } else {\n          p.shootTimer = Math.min(p.shootTimer, PEA_FIRST_DELAY);\n        }\n      } else if(p.type === \"repeaterpea\"){\n        if(p.secondShotT > 0){\n          p.secondShotT -= dt;\n          if(p.secondShotT <= 0){\n            bullets.push({x:p.cx+18, y:p.cy-6, row:y, dmg:BULLET_DAMAGE, anim:now});\n            p.secondShotT = 0;\n          }\n        }\n        let hasZ2 = false;\n        for(const z of zombies){ if(z.row===y && !z.dead && !z.hypno && z.x > p.cx){ hasZ2=true; break; } }\n        if(hasZ2){\n          p.shootTimer -= dt;\n          if(p.shootTimer <= 0){\n            p.shootTimer = PEA_INTERVAL;\n            bullets.push({x:p.cx+18, y:p.cy-6, row:y, dmg:BULLET_DAMAGE, anim:now});\n            p.secondShotT = 100;\n          }\n        } else {\n          p.shootTimer = Math.min(p.shootTimer, PEA_FIRST_DELAY);\n        }\n      } else if(p.type === \"snowpea\"){\n        let hasZ = false;\n        for(const z of zombies){ if(z.row===y && !z.dead && !z.hypno && z.x > p.cx){ hasZ=true; break; } }\n        if(hasZ){\n          p.shootTimer -= dt;\n          if(p.shootTimer <= 0){\n            p.shootTimer = PEA_INTERVAL;\n            bullets.push({x:p.cx+18, y:p.cy-6, row:y, dmg:BULLET_DAMAGE, anim:now, ice:true});\n          }\n        } else {\n          p.shootTimer = Math.min(p.shootTimer, PEA_FIRST_DELAY);\n        }\n      } else if(p.type === \"threepeater\"){\n        let hasZ3 = false;\n        for(let dy=-1;dy<=1;dy++){\n          const ry = y + dy;\n          if(ry < 0 || ry >= ROWS) continue;\n          for(const z of zombies){ if(z.row===ry && !z.dead && !z.hypno && z.x > p.cx){ hasZ3=true; break; } }\n        }\n        if(hasZ3){\n          p.shootTimer -= dt;\n          if(p.shootTimer <= 0){\n            p.shootTimer = PEA_INTERVAL;\n            for(let dy=-1;dy<=1;dy++){\n              const ry = y + dy;\n              if(ry < 0 || ry >= ROWS) continue;\n              const ty = GRID_Y+ry*CELL_H+CELL_H/2-6;\n              bullets.push({x:p.cx+18, y:p.cy-6, startY:p.cy-6, targetY:ty, startX:p.cx+18, row:ry, dmg:BULLET_DAMAGE, anim:now});\n            }\n          }\n        } else {\n          p.shootTimer = Math.min(p.shootTimer, PEA_FIRST_DELAY);\n        }\n      } else if(p.type === \"chomper\"){\n        if(p.chewing){\n          p.chewTimer -= dt;\n          if(p.chewTimer <= 0) p.chewing = false;\n        } else {\n          for(const z of zombies){\n            if(!z.dead && z.row===y && z.x > p.cx && z.x - p.cx < CELL_W*1.8){\n              z.hp = 0; z.dead = true;\n              if(!z._counted){ z._counted = true; killCount++; actionLog.push({t:now, e:\"kill\"}); }\n              spawnParticle(z.x, z.y, \"#9a5ab8\", 12);\n              p.chewing = true;\n              p.chewTimer = 30000;\n              break;\n            }\n          }\n        }\n      } else if(p.type === \"potatomine\"){\n        if(!p.armed){\n          p.armTimer -= dt;\n          if(p.armTimer <= 0) p.armed = true;\n        } else {\n          for(const z of zombies){\n            if(!z.dead && z.row===y && Math.abs(z.x - p.cx) < 30){\n              explode(p.cx, p.cy, POTATO_DAMAGE, y, 1);\n              p.hp = 0;\n              break;\n            }\n          }\n        }\n      } else if(p.type === \"cherrybomb\"){\n        p.fuse -= dt;\n        if(p.fuse <= 0){\n          explode(p.cx, p.cy, CHERRY_DAMAGE, y, 3);\n          p.hp = 0;\n        }\n      } else if(p.type === \"sunshroom\"){\n        if(!p.grown){\n          p.growTimer = (p.growTimer||SUNSHROOM_GROW) - dt;\n          if(p.growTimer <= 0) p.grown = true;\n        }\n        p.sunTimer -= dt;\n        if(p.sunTimer <= 0){\n          p.sunTimer = SUNFLOWER_INTERVAL;\n          p.bounceT = 300;\n          const ox = (rng()-0.5)*40;\n          const val = p.grown ? SUN_VALUE : SUNSHROOM_SMALL;\n          suns.push({x:p.cx+ox, y:p.cy-15, ty:p.cy+20, vy:-0.38, g:0.0014, bounced:0, anim:now, life:SUN_LIVE_TIME, falling:false, bouncing:true, value:val});\n        }\n      } else if(p.type === \"puffshroom\"){\n        let hasZ = false;\n        for(const z of zombies){\n          if(z.row===y && !z.dead && !z.hypno && z.x > p.cx && z.x - p.cx < PUFF_RANGE*CELL_W){ hasZ=true; break; }\n        }\n        if(hasZ){\n          p.shootTimer -= dt;\n          if(p.shootTimer <= 0){\n            p.shootTimer = PEA_INTERVAL;\n            bullets.push({x:p.cx+12, y:p.cy+2, row:y, dmg:BULLET_DAMAGE, anim:now, maxX:p.cx+PUFF_RANGE*CELL_W, puff:true, spore:true});\n          }\n        } else p.shootTimer = Math.min(p.shootTimer, PEA_FIRST_DELAY);\n      } else if(p.type === \"fumeshroom\"){\n        let hasZ = false;\n        for(const z of zombies){\n          if(z.row===y && !z.dead && !z.hypno && z.x > p.cx && z.x - p.cx < FUME_RANGE*CELL_W){ hasZ=true; break; }\n        }\n        if(hasZ){\n          p.shootTimer -= dt;\n          if(p.shootTimer <= 0){\n            p.shootTimer = 900;\n            for(const z of zombies){\n              if(z.row===y && !z.dead && !z.hypno && z.x > p.cx && z.x - p.cx < FUME_RANGE*CELL_W){\n                damageZombie(z, 20);\n                z.hitFlash = 80;\n              }\n            }\n            fumeFx.push({ x: p.cx + 20, y: p.cy - 2, len: FUME_RANGE*CELL_W, life: 450, maxLife: 450, seed: rng()*100 });\n            p.puffT = 260;\n          }\n        } else p.shootTimer = Math.min(p.shootTimer||0, 400);\n      } else if(p.type === \"scaredyshroom\"){\n        let near = false, hasZ = false;\n        for(const z of zombies){\n          if(z.row!==y || z.dead || z.hypno) continue;\n          if(z.x > p.cx){\n            hasZ = true;\n            if(z.x - p.cx < CELL_W*1.6) near = true;\n          }\n        }\n        p.hiding = near;\n        if(hasZ && !near){\n          p.shootTimer -= dt;\n          if(p.shootTimer <= 0){\n            p.shootTimer = PEA_INTERVAL;\n            bullets.push({x:p.cx+14, y:p.cy-8, row:y, dmg:BULLET_DAMAGE, anim:now, spore:true});\n          }\n        } else p.shootTimer = Math.min(p.shootTimer||PEA_FIRST_DELAY, PEA_FIRST_DELAY);\n      } else if(p.type === \"gravebuster\"){\n        p.eatTimer -= dt;\n        if(p.eatTimer <= 0){\n          removeGrave(p.gx, p.gy);\n          p.hp = 0;\n          spawnParticle(p.cx, p.cy, \"#5a8a4a\", 10);\n        }\n      } else if(p.type === \"iceshroom\"){\n        p.fuse -= dt;\n        if(p.fuse <= 0){\n          for(const z of zombies){\n            if(!z.dead && !z.hypno){ z.frozen = ICE_SHROOM_FREEZE; z.slowed = ICE_SHROOM_FREEZE; }\n          }\n          spawnParticle(p.cx, p.cy, \"#70d0f0\", 24);\n          p.hp = 0;\n        }\n      } else if(p.type === \"doomshroom\"){\n        p.fuse -= dt;\n        if(p.fuse <= 0){\n          explode(p.cx, p.cy, DOOM_DAMAGE, y, DOOM_RANGE, \"doom\");\n          /* 留下弹坑 */\n          const cell = cellAt(p.cx, p.cy);\n          if(cell && !craters.some(c => c.x===cell.x && c.y===cell.y)){\n            craters.push({ x: cell.x, y: cell.y });\n          }\n          p.hp = 0;\n        }\n      }\n    }\n  }\n  for(let y=0;y<ROWS;y++){\n    for(let x=0;x<COLS;x++){\n      if(grid[y][x] && grid[y][x].hp <= 0) grid[y][x] = null;\n    }\n  }\n\n  /* 子弹更新 */\n  for(let i=bullets.length-1;i>=0;i--){\n    const b = bullets[i];\n    b.x += BULLET_SPEED*dt/1000;\n    b.anim = now;\n    if(b.targetY !== undefined){\n      const t = Math.min(1, (b.x - b.startX) / (CELL_W * 0.6));\n      b.y = b.startY + (b.targetY - b.startY) * t;\n    }\n    if(b.maxX != null && b.x > b.maxX){ bullets.splice(i,1); continue; }\n    if(b.x > SPAWN_X+20){ bullets.splice(i,1); continue; }\n    for(const z of zombies){\n      if(z.dead || z.hypno || z.row !== b.row) continue;\n      if(Math.abs(z.x - b.x) < 16){\n        damageZombie(z, b.dmg);\n        z.hitFlash = 100;\n        if(b.ice) z.slowed = 5000;\n        bullets.splice(i,1);\n        spawnParticle(b.x, b.y, z.helmet>0?((z.kind===\"buckethead\"||z.kind===\"football\"||z.kind===\"screendoor\")?\"#aaa\":(z.kind===\"newspaper\"?\"#d8c8a0\":\"#e8822a\")):(b.spore?\"#c8a0e8\":(b.ice?\"#b0e8ff\":\"#a8e07a\")), 4);\n        break;\n      }\n    }\n  }\n\n  /* 最终大波：墓碑冒僵尸 */\n  if(isNightLevel() && !graveSpawnDone && waveIndex > 0 && waveIndex === NUM_FLAGS*10){\n    graveSpawnDone = true;\n    for(const g of graves){\n      const cy = GRID_Y + g.y*CELL_H + CELL_H/2 + 6;\n      const c = cellCenter(g.x, g.y);\n      const zt = ZOMBIE_TYPES.normal;\n      zombies.push({\n        x: c.x, y: cy, row:g.y, kind:\"normal\",\n        hp: zt.hp, helmet:0, maxHelmet:0, speedMul: getDiff().speedMul,\n        anim: now, walkT:0, attackT:0, dead:false,\n        hasPole:false, jumping:false, jumpProgress:0, slowed:0, enraged:false, hypno:false, frozen:0\n      });\n    }\n  }\n\n  /* 僵尸更新 */\n  for(let i=zombies.length-1;i>=0;i--){\n    const z = zombies[i];\n    if(z.dead){ zombies.splice(i,1); continue; }\n    z.anim = now;\n    if(z.hitFlash>0) z.hitFlash -= dt;\n    if(z.frozen > 0){ z.frozen -= dt; continue; }\n\n    /* 魅惑僵尸：向右走并撞击敌方僵尸 */\n    if(z.hypno){\n      z.x += ZOMBIE_SPEED * 1.2 * (z.speedMul||1) * dt/1000;\n      for(const o of zombies){\n        if(o===z || o.dead || o.hypno) continue;\n        if(o.row===z.row && Math.abs(o.x-z.x)<22){\n          damageZombie(o, 40); o.hitFlash=80;\n          z.hp -= 30;\n        }\n      }\n      if(z.x > SPAWN_X+40 || z.hp <= 0){\n        z.dead = true;\n        if(z.hp<=0 && !z._counted){ z._counted=true; killCount++; actionLog.push({t:now,e:\"kill\"}); }\n      }\n      continue;\n    }\n\n    /* 舞王召唤伴舞 */\n    if(z.kind === \"dancing\"){\n      z.danceTimer = (z.danceTimer==null ? 2500 : z.danceTimer) - dt;\n      if(z.danceTimer <= 0){\n        z.danceTimer = 9000;\n        for(const dy of [-1,0,1]){\n          const ry = z.row + dy;\n          if(ry<0||ry>=ROWS) continue;\n          if(dy===0 && rng()<0.4) continue;\n          const zt = ZOMBIE_TYPES.backup;\n          zombies.push({\n            x: z.x + 20 + rng()*30, y: GRID_Y+ry*CELL_H+CELL_H/2+6, row:ry, kind:\"backup\",\n            hp: Math.round(zt.hp*getDiff().hpMul), helmet:0, maxHelmet:0,\n            speedMul: getDiff().speedMul, anim:now, walkT:0, attackT:0, dead:false,\n            hasPole:false, jumping:false, jumpProgress:0, slowed:0, enraged:false, hypno:false, frozen:0\n          });\n        }\n      }\n    }\n\n    /* 撑杆跳跳跃中 */\n    if(z.jumping){\n      z.jumpProgress += dt/600;\n      z.x -= CELL_W*1.5*dt/600;\n      if(z.jumpProgress >= 1){\n        z.jumping = false;\n        z.jumpProgress = 0;\n        z.hasPole = false;\n      }\n      continue;\n    }\n\n    /* 检测前方植物 */\n    let target = null;\n    for(let x=0;x<COLS;x++){\n      const p = grid[z.row][x];\n      if(p && Math.abs(z.x - p.cx) < 28){ target = {p:p, x:x}; break; }\n    }\n\n    /* 撑杆跳僵尸有杆子时跳过第一个植物 */\n    if(target && z.hasPole && z.kind === \"polevaulter\"){\n      z.jumping = true;\n      z.jumpProgress = 0;\n      continue;\n    }\n\n    if(target){\n      z.attackT -= dt;\n      if(z.attackT <= 0){\n        z.attackT = ZOMBIE_ATTACK_INTERVAL;\n        if(target.p.type === \"hypnoshroom\"){\n          z.hypno = true;\n          z.helmet = 0;\n          target.p.hp = 0;\n          spawnParticle(z.x, z.y, \"#d060c0\", 12);\n        } else {\n          target.p.hp -= ZOMBIE_DAMAGE;\n        }\n      }\n    } else {\n      if(z.kind===\"newspaper\" && z.helmet<=0 && !z.enraged){ z.enraged = true; }\n      let spd = ZOMBIE_SPEED;\n      if(z.kind===\"polevaulter\" && z.hasPole) spd = ZOMBIE_SPEED*1.5;\n      else if(ZOMBIE_TYPES[z.kind] && ZOMBIE_TYPES[z.kind].speed) spd = ZOMBIE_SPEED * ZOMBIE_TYPES[z.kind].speed;\n      if(z.enraged) spd *= 2;\n      if(z.slowed > 0){ z.slowed -= dt; spd *= 0.5; }\n      spd *= (z.speedMul || 1);\n      z.x -= spd*dt/1000;\n      if(z.x < HOUSE_X){\n        const my = z.row;\n        if(mowers[my]){\n          mowers[my] = false;\n          mowerEntities.push({\n            x: GRID_X - 30, cy: GRID_Y + my*CELL_H + CELL_H/2,\n            row: my, anim: now\n          });\n        } else {\n          lose();\n          return;\n        }\n      }\n    }\n    if(z.hp <= 0){\n      z.dead = true;\n      if(!z._counted){\n        z._counted = true;\n        killCount++;\n        spawnParticle(z.x, z.y, \"#b5c098\", 6);\n        actionLog.push({t:now, e:\"kill\"});\n      }\n    }\n  }\n\n  /* 割草机行驶 */\n  for(let i=mowerEntities.length-1;i>=0;i--){\n    const m = mowerEntities[i];\n    m.anim = now;\n    m.x += MOWER_SPEED*dt/1000;\n    for(const z of zombies){\n      if(!z.dead && z.row===m.row && Math.abs(z.x - (m.x+11)) < 22){\n        z.hp = 0; z.dead = true;\n        if(!z._counted){ z._counted = true; killCount++; actionLog.push({t:now, e:\"kill\"}); }\n        spawnParticle(z.x, z.y, \"#b5c098\", 6);\n      }\n    }\n    if(rng() < 0.25){ spawnParticle(m.x+4, m.cy+6, \"#7ec850\", 1); }\n    if(m.x > W + 30) mowerEntities.splice(i,1);\n  }\n\n  /* 粒子更新 */\n  for(let i=particles.length-1;i>=0;i--){\n    const p = particles[i];\n    p.x += p.vx*dt/1000; p.y += p.vy*dt/1000;\n    p.vy += 200*dt/1000;\n    p.life -= dt;\n    if(p.life <= 0) particles.splice(i,1);\n  }\n  /* 爆炸特效寿命 */\n  for(let i=boomFx.length-1;i>=0;i--){\n    boomFx[i].life -= dt;\n    if(boomFx[i].life <= 0) boomFx.splice(i,1);\n  }\n  for(let i=fumeFx.length-1;i>=0;i--){\n    fumeFx[i].life -= dt;\n    if(fumeFx[i].life <= 0) fumeFx.splice(i,1);\n  }\n  for(let y=0;y<ROWS;y++){\n    for(let x=0;x<COLS;x++){\n      const p = grid[y][x];\n      if(p && p.puffT > 0) p.puffT -= dt;\n    }\n  }\n\n  /* 胜利判定（无尽模式永不自动胜利） */\n  if(!isEndless() && waveIndex >= NUM_FLAGS*10 && zombies.length === 0 && zombiesToSpawn.length === 0){\n    win();\n  }\n}\nlet mowers = [true,true,true,true,true];\n\n/* 对僵尸造成伤害：先扣防具，再扣本体 */\nfunction damageZombie(z, dmg){\n  if(z.helmet > 0){\n    z.helmet -= dmg;\n    if(z.helmet < 0){ z.hp += z.helmet; z.helmet = 0; }\n  } else {\n    z.hp -= dmg;\n  }\n  if(z.hp <= 0) z.dead = true;\n}\n\nfunction explode(cx, cy, dmg, row, range, kind){\n  const r = range == null ? 1 : range;\n  const k = kind || (r >= DOOM_RANGE ? \"doom\" : (r <= 1 ? \"potato\" : \"cherry\"));\n  /* range：切比雪夫距离（格）。土豆≈0.6，樱桃≈1.5，毁灭≈5 */\n  const cellRadius = r <= 1 ? 0.65 : (r <= 3 ? 1.5 : r * 0.85);\n  boomFx.push({\n    x: cx, y: cy, range: cellRadius, kind: k,\n    life: k === \"doom\" ? 900 : 500,\n    maxLife: k === \"doom\" ? 900 : 500\n  });\n  if(k === \"doom\"){\n    spawnParticle(cx, cy, \"#ff6a20\", 36);\n    spawnParticle(cx, cy, \"#ffd24a\", 28);\n    spawnParticle(cx, cy, \"#a020c0\", 24);\n    spawnParticle(cx, cy, \"#2a1020\", 18);\n  } else {\n    spawnParticle(cx, cy, \"#ff8c42\", 20);\n    spawnParticle(cx, cy, \"#ffd24a\", 15);\n  }\n  for(const z of zombies){\n    if(z.dead || z.hypno) continue;\n    if(r <= 1){\n      if(z.row === row && Math.abs(z.x - cx) < 55) damageZombie(z, dmg);\n    } else {\n      const dx = Math.abs(z.x - cx) / CELL_W;\n      const dy = Math.abs(z.y - cy) / CELL_H;\n      if(Math.max(dx, dy) <= cellRadius) damageZombie(z, dmg);\n    }\n  }\n}\nfunction spawnParticle(x,y,color,n){\n  for(let i=0;i<n;i++){\n    const a = rng()*Math.PI*2, sp = 40+rng()*120;\n    particles.push({x:x,y:y,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp-40,color:color,size:2+rng()*4,life:400+rng()*300,maxLife:700});\n  }\n}\nfunction drawBoomFx(fx){\n  const t = 1 - fx.life / fx.maxLife;\n  const alpha = 1 - t;\n  const rw = CELL_W * fx.range * 2 * (0.85 + t * 0.35);\n  const rh = CELL_H * fx.range * 2 * (0.85 + t * 0.35);\n  ctx.save();\n  if(fx.kind === \"doom\"){\n    ctx.fillStyle = \"rgba(255,220,160,\" + (0.35 * alpha) + \")\";\n    ctx.fillRect(0, 0, W, H);\n    ctx.fillStyle = \"rgba(160,40,200,\" + (0.18 * alpha) + \")\";\n    ctx.beginPath();\n    ctx.ellipse(fx.x, fx.y, rw * 0.55, rh * 0.55, 0, 0, 7);\n    ctx.fill();\n    ctx.strokeStyle = \"rgba(255,120,40,\" + (0.85 * alpha) + \")\";\n    ctx.lineWidth = 4;\n    ctx.beginPath();\n    ctx.ellipse(fx.x, fx.y, rw/2, rh/2, 0, 0, 7);\n    ctx.stroke();\n    ctx.strokeStyle = \"rgba(255,220,80,\" + (0.55 * alpha) + \")\";\n    ctx.lineWidth = 2;\n    ctx.beginPath();\n    ctx.ellipse(fx.x, fx.y, rw * 0.35 * (1 + t), rh * 0.35 * (1 + t), 0, 0, 7);\n    ctx.stroke();\n    /* 蘑菇云感 */\n    ctx.fillStyle = \"rgba(40,20,50,\" + (0.45 * alpha) + \")\";\n    ctx.beginPath(); ctx.ellipse(fx.x, fx.y - 20 - t * 30, 28 + t * 20, 22 + t * 16, 0, 0, 7); ctx.fill();\n    ctx.fillStyle = \"rgba(220,80,40,\" + (0.5 * alpha) + \")\";\n    ctx.beginPath(); ctx.ellipse(fx.x, fx.y - 10 - t * 18, 18 + t * 10, 14 + t * 8, 0, 0, 7); ctx.fill();\n  } else {\n    ctx.fillStyle = \"rgba(255,120,40,\" + (0.22 * alpha) + \")\";\n    ctx.beginPath();\n    ctx.ellipse(fx.x, fx.y, rw/2, rh/2, 0, 0, 7);\n    ctx.fill();\n    ctx.strokeStyle = \"rgba(255,200,80,\" + (0.7 * alpha) + \")\";\n    ctx.lineWidth = 3;\n    ctx.beginPath();\n    ctx.ellipse(fx.x, fx.y, rw/2, rh/2, 0, 0, 7);\n    ctx.stroke();\n  }\n  ctx.restore();\n}\nfunction drawFumeFx(fx){\n  const t = 1 - fx.life / fx.maxLife;\n  const alpha = t < 0.2 ? t / 0.2 : 1 - (t - 0.2) / 0.8;\n  const reach = fx.len * Math.min(1, t * 2.2);\n  ctx.save();\n  const g = ctx.createLinearGradient(fx.x, 0, fx.x + fx.len, 0);\n  g.addColorStop(0, \"rgba(170,110,220,\" + (0.55 * alpha) + \")\");\n  g.addColorStop(0.6, \"rgba(190,140,235,\" + (0.35 * alpha) + \")\");\n  g.addColorStop(1, \"rgba(210,170,245,0)\");\n  ctx.fillStyle = g;\n  ctx.beginPath();\n  ctx.moveTo(fx.x, fx.y - 7);\n  ctx.quadraticCurveTo(fx.x + reach * 0.5, fx.y - 22, fx.x + reach, fx.y - 16);\n  ctx.lineTo(fx.x + reach, fx.y + 16);\n  ctx.quadraticCurveTo(fx.x + reach * 0.5, fx.y + 22, fx.x, fx.y + 7);\n  ctx.closePath();\n  ctx.fill();\n  for(let i=0;i<9;i++){\n    const f = (i + 0.5) / 9;\n    if(f * fx.len > reach) break;\n    const px = fx.x + f * fx.len;\n    const py = fx.y + Math.sin(fx.seed + i * 1.7 + t * 6) * 9;\n    const r = 6 + f * 9 + t * 5;\n    ctx.fillStyle = \"rgba(200,155,240,\" + (0.4 * alpha * (1 - f * 0.5)) + \")\";\n    ctx.beginPath(); ctx.arc(px, py, r, 0, 7); ctx.fill();\n  }\n  ctx.restore();\n}\nfunction drawCraters(){\n  for(const c of craters){\n    const x = GRID_X + c.x * CELL_W + CELL_W/2;\n    const y = GRID_Y + c.y * CELL_H + CELL_H/2 + 8;\n    ctx.fillStyle = \"rgba(20,12,10,.55)\";\n    ctx.beginPath(); ctx.ellipse(x, y, 26, 14, 0, 0, 7); ctx.fill();\n    ctx.fillStyle = \"rgba(50,30,20,.45)\";\n    ctx.beginPath(); ctx.ellipse(x, y+2, 18, 8, 0, 0, 7); ctx.fill();\n    ctx.strokeStyle = \"rgba(80,50,30,.5)\";\n    ctx.lineWidth = 1.5;\n    ctx.beginPath(); ctx.ellipse(x, y, 26, 14, 0, 0, 7); ctx.stroke();\n  }\n}\nfunction hasCrater(cx, cy){\n  return craters.some(c => c.x === cx && c.y === cy);\n}\n\n/* ===== 渲染 ===== */\nfunction getWorldBtns(){\n  const items = [{id:\"day\", label:\"☀ 白天\"}, {id:\"night\", label:\"🌙 黑夜\"}];\n  const bw = 120, bh = 32, gap = 14;\n  const total = items.length*bw + (items.length-1)*gap;\n  const x0 = W/2 - total/2, y = 102;\n  return items.map((it,i)=>({ ...it, x:x0+i*(bw+gap), y, w:bw, h:bh }));\n}\nfunction getDiffBtns(){\n  const bw = 90, bh = 30, gap = 10;\n  const total = DIFF_ORDER.length*bw + (DIFF_ORDER.length-1)*gap;\n  const x0 = W/2 - total/2, y = 148;\n  return DIFF_ORDER.map((id,i)=>({ id, x:x0+i*(bw+gap), y, w:bw, h:bh }));\n}\nfunction getLevelBtns(){\n  const list = getWorldLevels();\n  const cols = 5, bw = 100, bh = 48, gapX = 10, gapY = 8;\n  const totalW = cols*bw + (cols-1)*gapX;\n  const x0 = W/2 - totalW/2, y0 = 200;\n  return list.map((lv,i)=>{\n    const col = i % cols, row = Math.floor(i / cols);\n    return { id:lv.id, lv, x:x0+col*(bw+gapX), y:y0+row*(bh+gapY), w:bw, h:bh };\n  });\n}\nconst ENDLESS_BTN = { w:200, h:44, get x(){return W/2-210;}, get y(){return 318;} };\nconst WEEKLY_BTN  = { w:200, h:44, get x(){return W/2+10;}, get y(){return 318;} };\nconst LB_BTN      = { w:220, h:38, get x(){return W/2-this.w/2;}, get y(){return 378;} };\nconst BACK_BTN    = { w:120, h:42, get x(){return W/2-this.w/2;}, get y(){return H-60;} };\nconst PAUSE_BTN   = { w:40, h:36, x: W-176, y: 10 };\nconst PAUSE_PANEL = { w:320, h:210, get x(){return W/2-this.w/2;}, get y(){return H/2-this.h/2;} };\nconst RESUME_BTN  = { w:240, h:52, get x(){return W/2-this.w/2;}, get y(){return PAUSE_PANEL.y+74;} };\nconst PMENU_BTN   = { w:240, h:52, get x(){return W/2-this.w/2;}, get y(){return RESUME_BTN.y+RESUME_BTN.h+18;} };\n\nfunction drawMenuBtn(b, label, colors, sub, now){\n  const hover = mouse.x>=b.x && mouse.x<=b.x+b.w && mouse.y>=b.y && mouse.y<=b.y+b.h;\n  ctx.save();\n  if(hover) ctx.translate(0, -2);\n  const g = ctx.createLinearGradient(0, b.y, 0, b.y+b.h);\n  g.addColorStop(0, hover ? colors[2] : colors[0]);\n  g.addColorStop(1, hover ? colors[3] : colors[1]);\n  ctx.fillStyle = g;\n  ctx.beginPath(); ctx.roundRect(b.x, b.y, b.w, b.h, 14); ctx.fill();\n  ctx.strokeStyle = \"rgba(255,255,255,.45)\"; ctx.lineWidth = 2;\n  ctx.beginPath(); ctx.roundRect(b.x+2, b.y+2, b.w-4, b.h-4, 12); ctx.stroke();\n  ctx.fillStyle = \"#fff\";\n  ctx.font = \"bold \" + (sub ? 18 : 20) + \"px sans-serif\"; ctx.textAlign = \"center\";\n  ctx.fillText(label, b.x+b.w/2, b.y + (sub ? b.h/2-2 : b.h/2+7));\n  if(sub){\n    ctx.font = \"11px sans-serif\"; ctx.fillStyle = \"rgba(255,255,255,.85)\";\n    ctx.fillText(sub, b.x+b.w/2, b.y+b.h-10);\n  }\n  ctx.restore();\n}\n\nfunction drawMenu(now){\n  ctx.clearRect(0,0,W,H);\n  drawBackground();\n  const veil = ctx.createLinearGradient(0,0,0,H);\n  veil.addColorStop(0,\"rgba(40,28,16,.62)\");\n  veil.addColorStop(1,\"rgba(30,40,18,.55)\");\n  ctx.fillStyle = veil;\n  ctx.fillRect(0,0,W,H);\n  for(let i=0;i<4;i++){\n    const sx = 120 + i*220 + Math.sin(now*0.0008+i)*24;\n    const sy = 70 + Math.cos(now*0.0006+i*2)*18;\n    ctx.save(); ctx.globalAlpha = 0.35;\n    drawSun({x:sx, y:sy, anim:now+i*1000});\n    ctx.restore();\n  }\n  ctx.textAlign = \"center\";\n  ctx.fillStyle = \"rgba(0,0,0,.35)\";\n  ctx.font = \"bold 42px sans-serif\";\n  ctx.fillText(\"植物大战僵尸\", W/2+2, 72);\n  ctx.fillStyle = \"#fff\";\n  ctx.fillText(\"植物大战僵尸\", W/2, 70);\n  ctx.font = \"bold 15px sans-serif\";\n  ctx.fillStyle = \"#ffd24a\";\n  ctx.fillText(curWorld===\"night\" ? \"黑夜冒险 2-1～2-10\" : \"白天冒险 1-1～1-10\", W/2, 92);\n\n  getWorldBtns().forEach(b=>{\n    const active = curWorld === b.id;\n    const hover = mouse.x>=b.x&&mouse.x<=b.x+b.w&&mouse.y>=b.y&&mouse.y<=b.y+b.h;\n    ctx.fillStyle = active ? (b.id===\"night\"?\"#5a3a88\":\"#5aa530\") : (hover?\"rgba(255,255,255,.28)\":\"rgba(255,255,255,.12)\");\n    ctx.beginPath(); ctx.roundRect(b.x, b.y, b.w, b.h, 16); ctx.fill();\n    ctx.strokeStyle = active ? \"#fff\" : \"rgba(255,255,255,.35)\";\n    ctx.lineWidth = active ? 2 : 1;\n    ctx.beginPath(); ctx.roundRect(b.x, b.y, b.w, b.h, 16); ctx.stroke();\n    ctx.fillStyle = \"#fff\";\n    ctx.font = \"bold 14px sans-serif\"; ctx.textAlign = \"center\";\n    ctx.fillText(b.label, b.x+b.w/2, b.y+b.h/2+5);\n  });\n\n  ctx.fillStyle = \"rgba(255,255,255,.65)\";\n  ctx.font = \"12px sans-serif\";\n  ctx.fillText(\"难度\", W/2, 140);\n  getDiffBtns().forEach(b=>{\n    const d = DIFFICULTIES[b.id];\n    const active = curDiff === b.id;\n    const hover = mouse.x>=b.x&&mouse.x<=b.x+b.w&&mouse.y>=b.y&&mouse.y<=b.y+b.h;\n    ctx.fillStyle = active ? d.color : (hover ? \"rgba(255,255,255,.28)\" : \"rgba(255,255,255,.14)\");\n    ctx.beginPath(); ctx.roundRect(b.x, b.y, b.w, b.h, 16); ctx.fill();\n    ctx.strokeStyle = active ? \"#fff\" : \"rgba(255,255,255,.4)\";\n    ctx.lineWidth = active ? 2 : 1;\n    ctx.beginPath(); ctx.roundRect(b.x, b.y, b.w, b.h, 16); ctx.stroke();\n    ctx.fillStyle = \"#fff\";\n    ctx.font = \"bold 14px sans-serif\"; ctx.textAlign = \"center\";\n    ctx.fillText(d.name, b.x+b.w/2, b.y+b.h/2+5);\n  });\n\n  ctx.fillStyle = \"rgba(255,255,255,.65)\";\n  ctx.font = \"12px sans-serif\";\n  ctx.fillText(\"选择关卡\", W/2, 190);\n  getLevelBtns().forEach(b=>{\n    const hover = mouse.x>=b.x&&mouse.x<=b.x+b.w&&mouse.y>=b.y&&mouse.y<=b.y+b.h;\n    ctx.save();\n    if(hover) ctx.translate(0,-2);\n    const g = ctx.createLinearGradient(0, b.y, 0, b.y+b.h);\n    const last = b.id === (curWorld===\"night\"?CLEAR_NIGHT_ID:CLEAR_DAY_ID);\n    if(last){ g.addColorStop(0,\"#e8822a\"); g.addColorStop(1,\"#c04820\"); }\n    else if(curWorld===\"night\"){ g.addColorStop(0, hover?\"#9a70d0\":\"#6a48a0\"); g.addColorStop(1, hover?\"#7a50b0\":\"#4a3080\"); }\n    else if(b.id >= 5){ g.addColorStop(0, hover?\"#9ed060\":\"#6cb840\"); g.addColorStop(1, hover?\"#5aa530\":\"#3a8a20\"); }\n    else { g.addColorStop(0, hover?\"#9ee070\":\"#7ec850\"); g.addColorStop(1, hover?\"#6cb840\":\"#4a9a2c\"); }\n    ctx.fillStyle = g;\n    ctx.beginPath(); ctx.roundRect(b.x, b.y, b.w, b.h, 10); ctx.fill();\n    ctx.strokeStyle = \"rgba(255,255,255,.45)\"; ctx.lineWidth = 2;\n    ctx.beginPath(); ctx.roundRect(b.x+1, b.y+1, b.w-2, b.h-2, 9); ctx.stroke();\n    ctx.fillStyle = \"#fff\";\n    ctx.font = \"bold 14px sans-serif\"; ctx.textAlign = \"center\";\n    ctx.fillText(b.lv.title.replace(/^(白天|黑夜) /,\"\"), b.x+b.w/2, b.y+20);\n    ctx.font = \"10px sans-serif\"; ctx.fillStyle = \"rgba(255,255,255,.88)\";\n    ctx.fillText(b.lv.sub, b.x+b.w/2, b.y+38);\n    ctx.restore();\n  });\n\n  drawMenuBtn(ENDLESS_BTN, \"∞ 无尽模式\", [\"#e07040\",\"#c04020\",\"#f09060\",\"#e0584c\"],\n    bestEndlessWave>0 ? (\"最佳 \"+bestEndlessWave+\" 波\") : \"波次无限升级\", now);\n  drawMenuBtn(WEEKLY_BTN, \"⚔ 每周挑战\", [\"#8a5ec8\",\"#5a3a98\",\"#b07ce8\",\"#7a4ec0\"],\n    window.__WEEK__ ? (\"本周 \"+window.__WEEK__.id) : \"阵容每周轮换\", now);\n  drawMenuBtn(LB_BTN, \"🏆 通关排行榜\", [\"rgba(255,255,255,.18)\",\"rgba(255,255,255,.1)\",\"rgba(255,255,255,.3)\",\"rgba(255,255,255,.18)\"], null, now);\n\n  ctx.fillStyle = \"rgba(255,255,255,.55)\";\n  ctx.font = \"12px sans-serif\"; ctx.textAlign = \"center\";\n  ctx.fillText(\"当前：\" + (curWorld===\"night\"?\"黑夜\":\"白天\") + \" · \" + getDiff().name + \" · 通关终章记入排行榜\", W/2, 432);\n}\n\n/* 排行榜面板 */\nfunction drawPickCard(key, x, y, w, h, opts){\n  const def = PLANTS[key];\n  const taken = !!(opts && opts.taken);\n  const hover = !!(opts && opts.hover);\n  const slot = !!(opts && opts.slot);\n  ctx.save();\n  ctx.fillStyle = taken ? \"rgba(40,50,42,.45)\" : (hover ? \"rgba(255,248,220,.96)\" : \"rgba(250,242,220,.94)\");\n  ctx.strokeStyle = hover ? \"#e8892c\" : (slot ? \"rgba(255,255,255,.28)\" : \"#c9a878\");\n  ctx.lineWidth = hover ? 2.5 : 1.5;\n  ctx.beginPath(); ctx.roundRect(x, y, w, h, 12); ctx.fill(); ctx.stroke();\n  if(def){\n    ctx.save();\n    ctx.translate(x + w/2, y + h * 0.38);\n    const sc = Math.min(0.58, w/100);\n    ctx.scale(sc, sc);\n    drawPlantIcon(key, performance.now(), 0);\n    ctx.restore();\n    ctx.fillStyle = taken ? \"rgba(90,80,70,.45)\" : \"#5a4a3a\";\n    ctx.font = \"bold 11px sans-serif\";\n    ctx.textAlign = \"center\";\n    ctx.fillText(def.name, x + w/2, y + h - 22);\n    ctx.fillStyle = taken ? \"rgba(160,80,60,.5)\" : \"#8b5a2b\";\n    ctx.font = \"bold 12px sans-serif\";\n    ctx.fillText(String(def.cost), x + w/2, y + h - 8);\n  } else if(slot){\n    ctx.fillStyle = \"rgba(255,255,255,.2)\";\n    ctx.font = \"24px sans-serif\";\n    ctx.textAlign = \"center\";\n    ctx.fillText(\"+\", x + w/2, y + h/2 + 8);\n  }\n  if(taken){\n    ctx.fillStyle = \"rgba(20,30,22,.35)\";\n    ctx.beginPath(); ctx.roundRect(x, y, w, h, 12); ctx.fill();\n  }\n  ctx.restore();\n}\nfunction drawPick(now){\n  ctx.clearRect(0,0,W,H);\n  drawBackground();\n  ctx.fillStyle = \"rgba(8,14,12,.62)\";\n  ctx.fillRect(0,0,W,H);\n  const L = getPickLayout();\n  ctx.textAlign = \"center\";\n  ctx.fillStyle = \"#fff\";\n  ctx.font = \"bold 28px sans-serif\";\n  ctx.fillText(\"选择你的植物\", W/2, 34);\n  ctx.fillStyle = \"rgba(247,241,227,.7)\";\n  ctx.font = \"13px sans-serif\";\n  ctx.fillText(\"可选 \" + MAX_SEED_SLOTS + \" 张 · 已选 \" + pickSelected.length + \" / \" + plantPool.length, W/2, 52);\n\n  for(let i=0;i<MAX_SEED_SLOTS;i++){\n    const x = L.bankX + i*(L.slotW + L.slotGap);\n    const key = pickSelected[i];\n    const hover = mouse.x>=x && mouse.x<=x+L.slotW && mouse.y>=L.bankY && mouse.y<=L.bankY+L.slotH;\n    if(key) drawPickCard(key, x, L.bankY, L.slotW, L.slotH, { hover: hover, slot: true });\n    else {\n      ctx.fillStyle = \"rgba(255,255,255,.08)\";\n      ctx.strokeStyle = \"rgba(255,255,255,.22)\";\n      ctx.lineWidth = 1.5;\n      ctx.setLineDash([5,4]);\n      ctx.beginPath(); ctx.roundRect(x, L.bankY, L.slotW, L.slotH, 12); ctx.fill(); ctx.stroke();\n      ctx.setLineDash([]);\n      ctx.fillStyle = \"rgba(255,255,255,.35)\";\n      ctx.font = \"20px sans-serif\"; ctx.textAlign = \"center\";\n      ctx.fillText(String(i+1), x+L.slotW/2, L.bankY+L.slotH/2+7);\n    }\n  }\n\n  ctx.fillStyle = \"rgba(247,241,227,.65)\";\n  ctx.font = \"13px sans-serif\"; ctx.textAlign = \"center\";\n  ctx.fillText(\"点击下方植物加入卡槽，再点卡槽可卸下\", W/2, L.poolY - 14);\n\n  plantPool.forEach((key, i)=>{\n    const col = i % L.poolCols;\n    const row = Math.floor(i / L.poolCols);\n    const x = L.poolX + col * (L.poolCardW + L.poolGapX);\n    const y = L.poolY + row * (L.poolCardH + L.poolGapY);\n    const taken = pickSelected.indexOf(key) >= 0;\n    const hover = !taken && mouse.x>=x && mouse.x<=x+L.poolCardW && mouse.y>=y && mouse.y<=y+L.poolCardH;\n    drawPickCard(key, x, y, L.poolCardW, L.poolCardH, { taken, hover });\n  });\n\n  const sb = L.startBtn;\n  const canStart = pickSelected.length > 0;\n  const sh = canStart && mouse.x>=sb.x && mouse.x<=sb.x+sb.w && mouse.y>=sb.y && mouse.y<=sb.y+sb.h;\n  const sg = ctx.createLinearGradient(sb.x, sb.y, sb.x, sb.y+sb.h);\n  if(canStart){\n    sg.addColorStop(0, sh ? \"#f0b04a\" : \"#f0a33a\");\n    sg.addColorStop(1, sh ? \"#e87a28\" : \"#e06a1a\");\n  } else {\n    sg.addColorStop(0, \"#6a6a6a\"); sg.addColorStop(1, \"#555\");\n  }\n  ctx.fillStyle = sg;\n  ctx.beginPath(); ctx.roundRect(sb.x, sb.y, sb.w, sb.h, 24); ctx.fill();\n  ctx.fillStyle = \"#fff\";\n  ctx.font = \"bold 18px sans-serif\"; ctx.textAlign = \"center\";\n  ctx.fillText(canStart ? (\"开始战斗 · \" + pickSelected.length + \" 张\") : \"请先选择植物\", sb.x+sb.w/2, sb.y+sb.h/2+6);\n\n  const bb = L.backBtn;\n  const bh = mouse.x>=bb.x && mouse.x<=bb.x+bb.w && mouse.y>=bb.y && mouse.y<=bb.y+bb.h;\n  ctx.fillStyle = bh ? \"rgba(255,255,255,.2)\" : \"rgba(255,255,255,.1)\";\n  ctx.strokeStyle = \"rgba(255,255,255,.28)\"; ctx.lineWidth = 1;\n  ctx.beginPath(); ctx.roundRect(bb.x, bb.y, bb.w, bb.h, 20); ctx.fill(); ctx.stroke();\n  ctx.fillStyle = \"#fff\";\n  ctx.font = \"bold 14px sans-serif\";\n  ctx.fillText(\"返回\", bb.x+bb.w/2, bb.y+bb.h/2+5);\n}\nfunction render(now){\n  if(state === \"menu\" || state === \"leaderboard\"){ return; }\n  if(state === \"pick\"){ drawPick(now); return; }\n  ctx.clearRect(0,0,W,H);\n  drawBackground();\n  if(selected && mouse.x>0){\n    const cell = cellAt(mouse.x, mouse.y);\n    if(cell){\n      const c = cellCenter(cell.x, cell.y);\n      const badGrave = (selected===\"gravebuster\") ? !hasGrave(cell.x,cell.y) : hasGrave(cell.x,cell.y);\n      const badCrater = selected!==\"gravebuster\" && hasCrater(cell.x, cell.y);\n      ctx.fillStyle = (grid[cell.y][cell.x] || sun < PLANTS[selected].cost || badGrave || badCrater) ? \"rgba(200,60,60,.25)\" : \"rgba(255,255,200,.35)\";\n      ctx.fillRect(GRID_X+cell.x*CELL_W, GRID_Y+cell.y*CELL_H, CELL_W, CELL_H);\n      ctx.strokeStyle = \"rgba(90,140,50,.6)\"; ctx.lineWidth = 2;\n      ctx.strokeRect(GRID_X+cell.x*CELL_W+1, GRID_Y+cell.y*CELL_H+1, CELL_W-2, CELL_H-2);\n    }\n  }\n  if(shovelActive && mouse.x>0){\n    const cell = cellAt(mouse.x, mouse.y);\n    if(cell && grid[cell.y][cell.x]){\n      ctx.fillStyle = \"rgba(200,140,40,.3)\";\n      ctx.fillRect(GRID_X+cell.x*CELL_W, GRID_Y+cell.y*CELL_H, CELL_W, CELL_H);\n    }\n  }\n  drawCraters();\n  for(let y=0;y<ROWS;y++){\n    for(let x=0;x<COLS;x++){\n      const p = grid[y][x];\n      if(p) drawPlant(p, p.cx, p.cy);\n    }\n  }\n  for(const s of suns) drawSun(s);\n  for(const b of bullets) drawBullet(b);\n  for(const z of zombies){ if(z.hitFlash>0){ ctx.globalAlpha=0.6; } drawZombie(z); ctx.globalAlpha=1; }\n  for(const m of mowerEntities) drawMowerBody(m.x, m.cy);\n  for(const fx of fumeFx) drawFumeFx(fx);\n  for(const fx of boomFx) drawBoomFx(fx);\n  for(const p of particles) drawParticle(p);\n  drawUI(now);\n  /* 暂停面板 */\n  if(paused){\n    ctx.fillStyle = \"rgba(20,15,10,.55)\";\n    ctx.fillRect(0,0,W,H);\n    const pp = PAUSE_PANEL;\n    ctx.fillStyle = \"#fef3e2\";\n    ctx.strokeStyle = \"#8b5a2b\"; ctx.lineWidth = 3;\n    ctx.beginPath(); ctx.roundRect(pp.x, pp.y, pp.w, pp.h, 16); ctx.fill(); ctx.stroke();\n    ctx.fillStyle = \"#8b5a2b\";\n    ctx.font = \"bold 30px sans-serif\"; ctx.textAlign = \"center\";\n    ctx.fillText(\"已暂停\", W/2, pp.y+48);\n    const pbtns = [[RESUME_BTN,\"▶ 继续游戏\",\"#7ec850\",\"#5aa530\"],[PMENU_BTN,\"🏠 返回主菜单\",\"#e0a030\",\"#c08020\"]];\n    for(const it of pbtns){\n      const bb = it[0];\n      const hover = mouse.x>=bb.x&&mouse.x<=bb.x+bb.w&&mouse.y>=bb.y&&mouse.y<=bb.y+bb.h;\n      ctx.save();\n      if(hover) ctx.translate(0,-2);\n      const g = ctx.createLinearGradient(0,bb.y,0,bb.y+bb.h);\n      g.addColorStop(0, hover?\"#9ee070\":it[1+1]); g.addColorStop(1, hover?\"#7ec850\":it[1+2]);\n      ctx.fillStyle = g;\n      ctx.beginPath(); ctx.roundRect(bb.x, bb.y, bb.w, bb.h, 12); ctx.fill();\n      ctx.fillStyle = \"#fff\";\n      ctx.font = \"bold 20px sans-serif\";\n      ctx.fillText(it[1], bb.x+bb.w/2, bb.y+bb.h/2+7);\n      ctx.restore();\n    }\n  }\n}\n\n/* ===== 输入 ===== */\nfunction getMouse(e){\n  const r = C.getBoundingClientRect();\n  return {\n    x: (e.clientX - r.left) * (W / r.width),\n    y: (e.clientY - r.top) * (H / r.height)\n  };\n}\nC.addEventListener(\"mousemove\", e=>{ const m=getMouse(e); mouse.x=m.x; mouse.y=m.y; });\nC.addEventListener(\"mouseleave\", ()=>{ mouse.x=-1; mouse.y=-1; });\nC.addEventListener(\"click\", e=>{\n  const m = getMouse(e); mouse.x=m.x; mouse.y=m.y;\n  /* 暂停面板：继续 / 返回主菜单 */\n  if(paused){\n    const rb = RESUME_BTN;\n    if(m.x>=rb.x&&m.x<=rb.x+rb.w&&m.y>=rb.y&&m.y<=rb.y+rb.h){ paused=false; return; }\n    const mb = PMENU_BTN;\n    if(m.x>=mb.x&&m.x<=mb.x+mb.w&&m.y>=mb.y&&m.y<=mb.y+mb.h){ paused=false; showLanding(); return; }\n    return;\n  }\n  if(state === \"menu\" || state === \"leaderboard\") return;\n  if(state === \"pick\"){\n    const L = getPickLayout();\n    const bb = L.backBtn;\n    if(m.x>=bb.x && m.x<=bb.x+bb.w && m.y>=bb.y && m.y<=bb.y+bb.h){\n      showLanding();\n      return;\n    }\n    const sb = L.startBtn;\n    if(m.x>=sb.x && m.x<=sb.x+sb.w && m.y>=sb.y && m.y<=sb.y+sb.h){\n      confirmPickAndStart();\n      return;\n    }\n    for(let i=0;i<pickSelected.length;i++){\n      const x = L.bankX + i*(L.slotW + L.slotGap);\n      if(m.x>=x && m.x<=x+L.slotW && m.y>=L.bankY && m.y<=L.bankY+L.slotH){\n        pickSelected.splice(i, 1);\n        return;\n      }\n    }\n    for(let i=0;i<plantPool.length;i++){\n      const col = i % L.poolCols;\n      const row = Math.floor(i / L.poolCols);\n      const x = L.poolX + col * (L.poolCardW + L.poolGapX);\n      const y = L.poolY + row * (L.poolCardH + L.poolGapY);\n      if(m.x>=x && m.x<=x+L.poolCardW && m.y>=y && m.y<=y+L.poolCardH){\n        const key = plantPool[i];\n        if(pickSelected.indexOf(key) >= 0) return;\n        if(pickSelected.length >= MAX_SEED_SLOTS) return;\n        pickSelected.push(key);\n        return;\n      }\n    }\n    return;\n  }\n  if(state !== \"play\") return;\n  /* 右上角暂停按钮 */\n  {\n    const pb = PAUSE_BTN;\n    if(m.x>=pb.x&&m.x<=pb.x+pb.w&&m.y>=pb.y&&m.y<=pb.y+pb.h){ paused=true; return; }\n  }\n  if(m.x >= W-130 && m.x <= W-16 && m.y >= 10 && m.y <= 46){\n    sunClickCount++;\n    if(sunClickCount >= 3){\n      cheatInput.style.display = \"block\";\n      cheatInput.focus();\n      sunClickCount = 0;\n    }\n    return;\n  }\n  let collectedAny = false;\n  for(let i=suns.length-1;i>=0;i--){\n    const s = suns[i];\n    if(!s.flying && Math.hypot(s.x-m.x, s.y-m.y) < 28){\n      s.flying = true;\n      s.flyT = 0;\n      s.flyDur = 300 + Math.hypot(s.x-SUN_BOX_X, s.y-SUN_BOX_Y)*0.4;\n      s.fromX = s.x; s.fromY = s.y;\n      s.toX = SUN_BOX_X; s.toY = SUN_BOX_Y;\n      s.falling = false;\n      spawnParticle(s.x, s.y, \"#ffd24a\", 6);\n      collectedAny = true;\n    }\n  }\n  if(collectedAny) return;\n  {\n    const { cardX0, cardY, cardW, cardH, gap } = getCardLayout();\n    if(m.x >= cardX0 && m.y >= cardY && m.y <= cardY+cardH){\n      curCardOrder.forEach((key, i)=>{\n        const x = cardX0 + i*(cardW+gap);\n        if(m.x >= x && m.x <= x+cardW){\n          if(cardCd[key] > performance.now() || sun < PLANTS[key].cost) return;\n          selected = (selected===key) ? null : key;\n          shovelActive = false;\n        }\n      });\n      const shX = cardX0 + curCardOrder.length*(cardW+gap) + 6;\n      if(m.x >= shX && m.x <= shX+44){\n        shovelActive = !shovelActive;\n        selected = null;\n      }\n      return;\n    }\n  }\n  const cell = cellAt(m.x, m.y);\n  if(cell){\n    if(shovelActive){\n      if(grid[cell.y][cell.x]){\n        grid[cell.y][cell.x] = null;\n        shovelActive = false;\n        actionLog.push({t:performance.now(), e:\"shovel\", x:cell.x, y:cell.y});\n      }\n    } else if(selected){\n      const onGrave = hasGrave(cell.x, cell.y);\n      if(selected === \"gravebuster\"){\n        if(!onGrave || grid[cell.y][cell.x] || sun < PLANTS.gravebuster.cost || cardCd.gravebuster > performance.now()) return;\n        const c = cellCenter(cell.x, cell.y);\n        const p = { type:\"gravebuster\", cx:c.x, cy:c.y+4, hp:PLANTS.gravebuster.hp, anim:performance.now(), eatTimer:4000, gx:cell.x, gy:cell.y };\n        grid[cell.y][cell.x] = p;\n        sun -= PLANTS.gravebuster.cost;\n        cardCd.gravebuster = performance.now() + PLANTS.gravebuster.cd;\n        actionLog.push({t:performance.now(), e:\"plant\", type:\"gravebuster\", x:cell.x, y:cell.y});\n        selected = null;\n        spawnParticle(c.x, c.y+10, \"#5a8a4a\", 6);\n        return;\n      }\n      if(onGrave) return; // 墓碑上不能种普通植物\n      if(hasCrater(cell.x, cell.y)) return; // 毁灭菇弹坑不能再种\n      if(!grid[cell.y][cell.x] && sun >= PLANTS[selected].cost && cardCd[selected] <= performance.now()){\n        const c = cellCenter(cell.x, cell.y);\n        const def = PLANTS[selected];\n        const p = { type:selected, cx:c.x, cy:c.y+4, hp:def.hp, anim:performance.now() };\n        if(selected===\"peashooter\" || selected===\"repeaterpea\" || selected===\"snowpea\" || selected===\"threepeater\" || selected===\"puffshroom\" || selected===\"fumeshroom\" || selected===\"scaredyshroom\") p.shootTimer = PEA_FIRST_DELAY;\n        if(selected===\"repeaterpea\") p.secondShotT = 0;\n        if(selected===\"chomper\"){ p.chewing=false; p.chewTimer=0; }\n        if(selected===\"sunflower\") p.sunTimer = SUNFLOWER_FIRST;\n        if(selected===\"sunshroom\"){ p.sunTimer = SUNFLOWER_FIRST; p.grown=false; p.growTimer=SUNSHROOM_GROW; }\n        if(selected===\"potatomine\"){ p.armed=false; p.armTimer=POTATO_ARM_TIME; }\n        if(selected===\"cherrybomb\" || selected===\"iceshroom\" || selected===\"doomshroom\") p.fuse = CHERRY_FUSE;\n        grid[cell.y][cell.x] = p;\n        sun -= def.cost;\n        cardCd[selected] = performance.now() + def.cd;\n        actionLog.push({t:performance.now(), e:\"plant\", type:selected, x:cell.x, y:cell.y});\n        selected = null;\n        spawnParticle(c.x, c.y+10, \"#7ec850\", 6);\n      }\n    }\n  }\n});\n\n/* ===== 胜负 ===== */\nfunction win(){\n  state = \"won\";\n  paused = false;\n  ovTitle.textContent = \"通关成功！\";\n  const dname = getDiff().name;\n  if(gameMode === \"weekly\"){\n    ovText.textContent = \"本周挑战通关！收集阳光 \" + collectedSun + \" 已记入周榜，多打多累积！\";\n  } else if(hasNextLevel()){\n    const nxt = nextLevelTarget();\n    ovText.textContent = curLevelMeta.title + \"（\" + dname + \"）通关！可以进入 \" + nxt.title + \"。\";\n  } else {\n    ovText.textContent = curLevelMeta.title + \"（\" + dname + \"）通关！击杀 \" + killCount + \" 只僵尸。\";\n  }\n  setOverlayActions(\"win\");\n  fillLeaderboardHTML();\n  overlay.classList.add(\"show\");\n  if(window.community && window.community.call){\n    window.community.call(\"finish\", {seed:gameSeed, actions:actionLog, result:\"win\", level:curLevel, world:curWorld, mode:gameMode, difficulty:curDiff, collectedSun:collectedSun, week:(window.__WEEK__&&window.__WEEK__.id)});\n  }\n}\nfunction lose(){\n  state = \"lost\";\n  paused = false;\n  if(isEndless()){\n    if(waveIndex > bestEndlessWave){\n      bestEndlessWave = waveIndex;\n      try { localStorage.setItem(\"pvz_endless_best\", String(bestEndlessWave)); } catch(e){}\n    }\n    ovTitle.textContent = \"无尽结束\";\n    ovText.textContent = \"撑到第 \" + waveIndex + \" 波，击杀 \" + killCount + \" 只！历史最佳 \" + bestEndlessWave + \" 波。\";\n    setOverlayActions(\"endless\");\n  } else {\n    ovTitle.textContent = \"游戏失败\";\n    ovText.textContent = \"僵尸吃掉了你的脑子！（\" + getDiff().name + \" · \" + curLevelMeta.title + \"）\";\n    setOverlayActions(\"lose\");\n  }\n  fillLeaderboardHTML();\n  overlay.classList.add(\"show\");\n  if(window.community && window.community.call){\n    window.community.call(\"finish\", {seed:gameSeed, actions:actionLog, result:\"lose\", level:curLevel, mode:gameMode, difficulty:curDiff, collectedSun:collectedSun, waves:waveIndex, kills:killCount, week:(window.__WEEK__&&window.__WEEK__.id)});\n  }\n}\novNextBtn.addEventListener(\"click\", ()=>{\n  if(state === \"won\" && hasNextLevel()){\n    const nxt = nextLevelTarget();\n    newGame(window.__SEED__, nxt.id, gameMode, nxt.world);\n  }\n});\novBtn.addEventListener(\"click\", ()=>{\n  newGame(window.__SEED__, isEndless() ? 0 : curLevel, gameMode, curWorld);\n});\novMenuBtn.addEventListener(\"click\", ()=>{\n  overlay.classList.remove(\"show\");\n  ovNextBtn.style.display = \"none\";\n  paused = false;\n  showLanding();\n});\n/* 作弊：在随机一路召唤指定类型僵尸 */\nfunction spawnCheatZombie(kind){\n  if(state !== \"play\") return;\n  const row = Math.floor(rng()*ROWS);\n  const cy = GRID_Y + row*CELL_H + CELL_H/2 + 6;\n  const zt = ZOMBIE_TYPES[kind] || ZOMBIE_TYPES.normal;\n  zombies.push({\n    x: SPAWN_X + rng()*30, y: cy, row:row, kind:kind,\n    hp: zt.hp, helmet: zt.helmet, maxHelmet: zt.helmet,\n    anim: performance.now(), walkT:0, attackT:0, attackTarget:null, dead:false,\n    hasPole: false, jumping:false, jumpProgress:0,\n    slowed: 0, enraged: false\n  });\n}\ncheatInput.addEventListener(\"keydown\", e=>{\n  if(e.key === \"Enter\"){\n    if(cheatInput.value === \"zard666\"){\n      cheatInput.value = \"\";\n      cheatInput.style.display = \"none\";\n      win();\n    } else if(cheatInput.value === \"zard999\"){\n      sun = 999;\n      cheatInput.value = \"\";\n      cheatInput.style.display = \"none\";\n    } else if(cheatInput.value === \"zarddb\"){\n      spawnCheatZombie(\"newspaper\");\n      cheatInput.value = \"\"; cheatInput.style.display = \"none\";\n    } else if(cheatInput.value === \"zardglq\"){\n      spawnCheatZombie(\"football\");\n      cheatInput.value = \"\"; cheatInput.style.display = \"none\";\n    } else if(cheatInput.value === \"zardtw\"){\n      spawnCheatZombie(\"screendoor\");\n      cheatInput.value = \"\"; cheatInput.style.display = \"none\";\n    } else {\n      cheatInput.style.display = \"none\";\n      cheatInput.value = \"\";\n    }\n  }\n  if(e.key === \"Escape\"){\n    cheatInput.style.display = \"none\";\n    cheatInput.value = \"\";\n  }\n  e.stopPropagation();\n});\ncheatInput.addEventListener(\"blur\", ()=>{\n  cheatInput.style.display = \"none\";\n  cheatInput.value = \"\";\n});\n\n/* ===== 主循环 ===== */\nfunction loop(t){\n  if(!lastTime) lastTime = t;\n  const dt = Math.min(t - lastTime, 50);\n  lastTime = t;\n  update(dt, t);\n  render(t);\n  requestAnimationFrame(loop);\n}\n\n/* polyfill: roundRect */\nif(!ctx.roundRect){\n  CanvasRenderingContext2D.prototype.roundRect = function(x,y,w,h,r){\n    if(typeof r===\"number\") r={tl:r,tr:r,br:r,bl:r};\n    this.beginPath();\n    this.moveTo(x+r.tl,y);\n    this.lineTo(x+w-r.tr,y); this.quadraticCurveTo(x+w,y,x+w,y+r.tr);\n    this.lineTo(x+w,y+h-r.br); this.quadraticCurveTo(x+w,y+h,x+w-r.br,y+h);\n    this.lineTo(x+r.bl,y+h); this.quadraticCurveTo(x,y+h,x,y+h-r.bl);\n    this.lineTo(x,y+r.tl); this.quadraticCurveTo(x,y,x+r.tl,y);\n    this.closePath();\n    return this;\n  };\n}\n\nstate = \"menu\";\nmouse = {x:-1, y:-1, click:false};\n/* 本地预览 fallback：服务端未注入 __WEEK__ 时，按当前日期生成（服务端注入会覆盖） */\nif(!window.__WEEK__){\n  const _wy = isoWeek(new Date());\n  window.__WEEK__ = { id: _wy, zombies: weeklyZombieSet(_wy) };\n}\nif(!window.__WEEK_LEADERBOARD__) window.__WEEK_LEADERBOARD__ = [];\nmowers = [true,true,true,true,true];\nmowerEntities = [];\nbindLandingUI();\nshowLanding();\n/* 快捷键：ESC / P 切换暂停（输入框聚焦时不触发） */\nwindow.addEventListener(\"keydown\", e=>{\n  if(document.activeElement && document.activeElement.tagName === \"INPUT\") return;\n  if(state === \"play\" && (e.key === \"Escape\" || e.key === \"p\" || e.key === \"P\")){\n    paused = !paused;\n    e.preventDefault();\n  }\n});\nrequestAnimationFrame(loop);\n";

// 服务端工具：ISO 周数 + 每周僵尸组合（须与前端 index.html 实现完全一致）
function _rng(seed){ let s = seed >>> 0 || 1; return function(){ s = (s*1664525+1013904223)>>>0; return s/4294967296; }; }
function isoWeek(d){
  const date = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  const dayNum = date.getUTCDay() || 7;
  date.setUTCDate(date.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(),0,1));
  const weekNum = Math.ceil((((date - yearStart)/86400000) + 1)/7);
  return date.getUTCFullYear() + "W" + String(weekNum).padStart(2,"0");
}
function weeklyZombieSet(yearWeek){
  return ["normal","flag","newspaper","football","screendoor","conehead","buckethead","polevaulter"];
}

// render 返回标题 + 通关排行榜，webview iframe 在其下方渲染。
export async function render(ctx, api) {
  let best = 0;
  try { best = (await api.kv.get("best")) ?? 0; } catch(e) {}

  // 读取共享区排行榜（通关次数榜 + 当周阳光榜）
  const yearWeek = isoWeek(new Date());
  let leaderboard = [];
  let weekLeaderboard = [];
  try {
    const all = await api.kv.listPublic();
    const entries = [];
    const sunEntries = [];
    const wPrefix = "wsun_" + yearWeek + "_";
    const wnPrefix = "wname_" + yearWeek + "_";
    for (const k of Object.keys(all)) {
      if (k.startsWith("clear_")) {
        const uid = k.slice(6);
        const name = all["name_" + uid] || "匿名玩家";
        const count = parseInt(all[k]) || 0;
        entries.push({ name, count });
      } else if (k.startsWith(wPrefix)) {
        const uid = k.slice(wPrefix.length);
        const name = all[wnPrefix + uid] || "匿名玩家";
        const sun = parseInt(all[k]) || 0;
        sunEntries.push({ name, sun });
      }
    }
    entries.sort((a, b) => b.count - a.count);
    leaderboard = entries.slice(0, 10);
    sunEntries.sort((a, b) => b.sun - a.sun);
    weekLeaderboard = sunEntries.slice(0, 10);
  } catch(e) {}

  const children = [
    { type: "text", value: "植物大战僵尸 · 庭院防线", size: "xl", weight: "bold" },
    { type: "text", value: "白天 1-10 · 黑夜 2-10 · 难度/无尽/每周挑战", size: "medium" },
    { type: "text", value: "🏆 通关排行榜", size: "large", weight: "bold" }
  ];
  if (leaderboard.length === 0) {
    children.push({ type: "text", value: "暂无通关记录，快来成为第一个通关的人！", size: "medium" });
  } else {
    leaderboard.forEach((e, i) => {
      const medal = i === 0 ? "🥇" : i === 1 ? "🥈" : i === 2 ? "🥉" : (i+1)+".";
      children.push({ type: "text", value: medal + " " + e.name + " — 通关 " + e.count + " 次", size: "medium" });
    });
  }

  children.push({ type: "text", value: "☀ 本周排行榜 · " + yearWeek + "（每周一刷新）", size: "large", weight: "bold" });
  if (weekLeaderboard.length === 0) {
    children.push({ type: "text", value: "本周暂无记录，参与「每周挑战」通关即可上榜，多打多累积！", size: "medium" });
  } else {
    weekLeaderboard.forEach((e, i) => {
      const medal = i === 0 ? "🥇" : i === 1 ? "🥈" : i === 2 ? "🥉" : (i+1)+".";
      children.push({ type: "text", value: medal + " " + e.name + " — 阳光 " + e.sun, size: "medium" });
    });
  }

  return {
    blocks: { type: "vstack", align: "center", padding: "medium", gap: "small", children },
    state: {},
    effects: []
  };
}

// 生成页面：种子注入在脚本最前面，让 newGame 能读到。
export async function webview(ctx, api) {
  const seed = ((Date.now() ^ Math.floor(Math.random() * 1e9)) >>> 0) || 1;

  // 服务端确定本周（防伪：不信任客户端）
  const yearWeek = isoWeek(new Date());
  const weeklySet = weeklyZombieSet(yearWeek);

  // 读取共享区排行榜，注入页面
  // listPublic 可能返回 {key:value} 或 [{key,value}]，两种都兼容
  let leaderboard = [];
  let weekLeaderboard = [];
  try {
    const all = await api.kv.listPublic();
    const getVal = (key) => {
      if (Array.isArray(all)) {
        const item = all.find(x => (x.key||x[0]) === key);
        return item ? (item.value ?? item[1]) : undefined;
      }
      return all[key];
    };
    const keys = Array.isArray(all) ? all.map(x => x.key || x[0]) : Object.keys(all);
    const entries = [];
    const sunEntries = [];
    const wPrefix = "wsun_" + yearWeek + "_";
    const wnPrefix = "wname_" + yearWeek + "_";
    for (const k of keys) {
      if (!k) continue;
      if (k.startsWith("clear_")) {
        const uid = k.slice(6);
        const name = getVal("name_" + uid) || "匿名玩家";
        const count = parseInt(getVal(k)) || 0;
        entries.push({ name, count });
      } else if (k.startsWith(wPrefix)) {
        const uid = k.slice(wPrefix.length);
        const name = getVal(wnPrefix + uid) || "匿名玩家";
        const sun = parseInt(getVal(k)) || 0;
        sunEntries.push({ name, sun });
      }
    }
    entries.sort((a, b) => b.count - a.count);
    leaderboard = entries.slice(0, 10);
    sunEntries.sort((a, b) => b.sun - a.sun);
    weekLeaderboard = sunEntries.slice(0, 10);
  } catch(e) {}

  const inject = "window.__SEED__=" + seed + ";window.__LEADERBOARD__=" + JSON.stringify(leaderboard) + ";window.__WEEK__=" + JSON.stringify({id:yearWeek, zombies:weeklySet}) + ";window.__WEEK_LEADERBOARD__=" + JSON.stringify(weekLeaderboard) + ";\n";
  const js = inject + GAME_JS;
  return {
    html: GAME_HTML,
    css: GAME_CSS,
    js: js,
  };
}

// 客户端通过 window.community.call("finish", {seed, actions, result}) 上报结果。
// 页面的分数不可信，这里用种子回放重算击杀数，并更新排行榜。
export async function onMessage(ctx, api) {
  if (ctx.method !== "finish") {
    return { blocks: null, state: null, effects: [] };
  }
  const { seed, actions, result, level, mode, collectedSun, difficulty, world } = ctx.params || {};
  const kills = replay(seed, actions, mode);
  const effects = [];

  // 个人最高击杀
  let best = 0;
  try { best = (await api.kv.get("best")) ?? 0; } catch(e) {}
  if ((result === "win" || mode === "endless") && kills > best) {
    effects.push({ type: "kv.set", key: "best", value: kills });
  }

  // 通关排行榜：通关白天 1-10 或黑夜 2-10（普通/困难）才记入
  const isClearFinal = level === 9 && (world === "day" || world === "night" || world == null);
  if (result === "win" && isClearFinal && mode === "normal" && difficulty !== "easy" && ctx.user) {
    try {
      let clearCount = 0;
      try { clearCount = parseInt((await api.kv.get("clears")) ?? 0) || 0; } catch(e) {}
      clearCount += 1;
      effects.push({ type: "kv.set", key: "clears", value: clearCount });
      const uid = String(ctx.user.id);
      // 官方文档：ctx.user 只含 id/username/avatar_url，username 才是真名
      const uname = ctx.user.username || ("玩家" + uid.slice(-4));
      effects.push({ type: "kv.shared.set", key: "clear_" + uid, value: String(clearCount) });
      effects.push({ type: "kv.shared.set", key: "name_" + uid, value: uname });
    } catch(e) {}
  }

  // 周阳光榜：仅 weekly 模式 + 胜利（周标识以服务端为准，防伪；collectedSun 单局上限 5000）
  if (mode === "weekly" && result === "win" && ctx.user) {
    try {
      const sun = Math.min(parseInt(collectedSun) || 0, 5000);
      if (sun > 0) {
        const serverWeek = isoWeek(new Date());
        const uid = String(ctx.user.id);
        const uname = ctx.user.username || ("玩家" + uid.slice(-4));
        const wkey = "wsun_" + serverWeek + "_" + uid;
        let prev = 0;
        try {
          const all = await api.kv.listPublic();
          const getVal = (key) => {
            if (Array.isArray(all)) { const it = all.find(x => (x.key||x[0]) === key); return it ? (it.value ?? it[1]) : undefined; }
            return all[key];
          };
          prev = parseInt(getVal(wkey)) || 0;
        } catch(e) {}
        effects.push({ type: "kv.shared.set", key: wkey, value: String(prev + sun) });
        effects.push({ type: "kv.shared.set", key: "wname_" + serverWeek + "_" + uid, value: uname });
      }
    } catch(e) {}
  }

  return { blocks: null, state: null, effects };
}

// 简化回放：用相同种子校验操作序列的合法性，统计击杀数。
// 真实场景应完整重放游戏模拟逻辑；这里校验种子有效且操作结构合法。
function replay(seed, actions, mode) {
  if (!Number.isInteger(seed) || !Array.isArray(actions)) return 0;
  let kills = 0;
  for (const a of actions) {
    if (a && a.e === "kill") kills++;
  }
  // 击杀数上限：冒险模式 / 无尽模式
  return Math.min(kills, mode === "endless" ? 5000 : 500);
}
